```rust
use notify_rust::{RecommendedWatcher, ConfigBuilder, RecursiveMode};
use notify_rust::event::{EventKind, AccessMode, Metadata, FileKind, RawAccessMode, ModificationTime, Mode, Size, Time};
use std::time::SystemTime;
use parking_lot::Mutex;

pub struct EventHandler {
    watcher: RecommendedWatcher,
}

impl EventHandler {
    pub fn start(watch_path: &std::path::Path) -> Result<Self, notify_rust::Error> {
        let mut builder = ConfigBuilder::default();
        builder.recommended()?;

        let (tx, rx) = std::sync::mpsc::channel::<notify_rust::Result<Event>>();
        let _ = builder.notify_stream(tx);

        let mut watcher = builder
            .recursive_mode(true)
            .create_watcher(tx)?;

        watcher.watch(watch_path, RecursiveMode::Recursive)?;

        Ok(Self { watcher })
    }

    pub fn get_config(&self) -> &ConfigBuilder {
        self.watcher.config()
    }

    pub fn stop(&mut self) {
        self.watcher.cancel_watches_all().ok();
    }
}
