                  <button
                    onClick={() => handleSelectOption(option)}
                    className={`flex w-full items-center justify-between px-4 py-3 text-left text-sm outline-none group ${
                      inputValue === option.label ? 'bg-blue-50 text-blue-900' : 'hover:bg-gray-100 text-gray-900'
