                  {/* Visual separator between items if many exist */}
                  {index < Math.max(filteredOptions.length - 1, 0) && (
                     <div className="h-[1px] bg-gray-200 mx-2"></div>
                  )}
                </React.Fragment>
              );
            })}

            {filteredOptions.length > 0 && (
               <div className="px-4 py-2 text-right">
                 <span className="text-xs text-gray-400">{filteredOptions.length} items</span>
               </div>
            )}
