Для реализации кнопки рестарта нужно сделать следующее:

### 1. Куда подключать?
Так как ваши джойстики занимают шина A0-A3, используйте любой **свободный цифровой пин**.
В этом коде я выбрал пин **D2** (Arduino Uno / Nano).

**Схема подключения:**
1.  Один контакт кнопки — в пин **D2** платы Arduino.
2.  Другой контакт кнопки — в **GND** (масса).

### 2. Как работает логически?
Когда вы нажимаете кнопку, она замыкает пин D2 на землю. Код проверяет состояние этого пина. Если нажатие длится определенное время (например, 500 мс), чтобы избежать случайного случайного запуска при тряске рук, игра сбрасывается: мяч возвращается в центр, корт очищается, счетчик обновляется.

### 3. Исправленный код
Я добавил определение кнопки и логику сброса внутри функции `loop()`. Скопируйте этот код целиком:

```cpp
#include <SPI.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define JOYSTICK1_X A0
#define JOYSTICK1_Y A1
#define JOYSTICK2_X A2
#define JOYSTICK2_Y A3

// --- НАСТРОЙКИ КНОПКИ РЕСТАРТА ---
// Подключите кнопку сюда (D2) и к земле (GND)
const uint8_t RESET_BUTTON_PIN = 2; 
const unsigned long RESET_DEBOUNCE_TIME = 300; // Защита от двойного клика (мс)
const unsigned long LAST_RESET = 0;             // Запоминание времени последнего рестарта
// ----------------------------------

const unsigned long PADDLE_RATE = 33;
const unsigned long BALL_RATE = 40;
const uint8_t PADDLE_HEIGHT = 8;
const uint8_t BALL_SIZE = 3;

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 32

#define OLED_RESET 4
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

void drawCourt();
void resetGame();

uint8_t ball_x = 64, ball_y = 16;
int8_t ball_dir_x = 1, ball_dir_y = 1;
unsigned long ball_update;

unsigned long paddle_update;
const uint8_t CPU_X = 12;
uint8_t cpu_y = 8;

const uint8_t PLAYER_X = 115;
uint8_t player_y = 8;

void setup() {
    // Настройка режима кнопки для рестарта
    pinMode(RESET_BUTTON_PIN, INPUT_PULLUP); 

    display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
    display.display();

    unsigned long start = millis();

    display.clearDisplay();
    drawCourt();

    // Ждем пока пользователь увидит меню или загрузится интерфейс
    while (millis() - start < 2000);

    display.display();

    // Инициализация счетчика
    ball_update = millis();
    paddle_update = ball_update;

    // Сразу сбрасываем игру при старте, если хотите начать с пустого экрана, 
    // то можно вызвать resetGame(), но сейчас оставим начальные позиции.
}

void loop() {
    bool update = false;
    unsigned long time = millis();

    // --- ПРОВЕРКА КНОПКИ РЕСТАРТА ---
    if (digitalRead(RESET_BUTTON_PIN) == LOW) {
        // Проверка, чтобы кнопка не была зажата более одного раза за короткий срок (Debouncing)
        if (time > LAST_RESET + RESET_DEBOUNCE_TIME) {
            resetGame();
            LAST_RESET = time;
        }
    }
    // -------------------------------

    int joy1_x = analogRead(JOYSTICK1_X);
    int joy1_y = analogRead(JOYSTICK1_Y);
    int joy2_x = analogRead(JOYSTICK2_X);
    int joy2_y = analogRead(JOYSTICK2_Y);

    if (time > ball_update) {
        uint8_t new_x = ball_x + ball_dir_x;
        int new_y = ball_y + ball_dir_y; // Заменил тип на int для удобства проверки границ

        // Отскок от верхнего и нижнего края
        if (new_y < 0 || new_y >= SCREEN_HEIGHT - BALL_SIZE) {
            ball_dir_y = -ball_dir_y;
            new_y += ball_dir_y * 2; // Корректировка позиции после отскока
        }

        // Попадание в компьютер (слева)
        if (new_x <= CPU_X && new_y >= cpu_y && new_y <= cpu_y + PADDLE_HEIGHT) {
            ball_dir_x = -ball_dir_x; // Разворот
            new_x += ball_dir_x * 2;
        }

        // Попадание в игрока (справа)
        if (new_x >= PLAYER_X && new_y >= player_y && new_y <= player_y + PADDLE_HEIGHT) {
            ball_dir_x = -ball_dir_x; // Разворот
            new_x -= 1; // Корректировка
        }

        // Отрисовка старого мяча (стирание следа)
        display.fillRect(ball_x, ball_y, BALL_SIZE, BALL_SIZE, WHITE); 

        display.fillRect(new_x, new_y, BALL_SIZE, BALL_SIZE, BLACK);
        ball_x = new_x;
        ball_y = new_y;

        ball_update += BALL_RATE;

        update = true;
    }

    if (time > paddle_update) {
        paddle_update += PADDLE_RATE;

        // Обновление ПК
        display.drawFastHLine(CPU_X - 1, cpu_y - 1, 2, WHITE); // Старая позиция (для визуализации смены мест)

        if (joy1_y < 400) {
            cpu_y = max(1, cpu_y - 1);
        } else if (joy1_y > 600) {
            cpu_y = min(31 - PADDLE_HEIGHT, cpu_y + 1);
        }

        // Обновление Игрока
        if (joy2_y < 400) {
            player_y = max(1, player_y - 1);
        } else if (joy2_y > 600) {
            player_y = min(31 - PADDLE_HEIGHT, player_y + 1);
        }

        // Простая очистка старых линий и рисование новых вертикалей (как было в оригинале)
        display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, WHITE);
        display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, WHITE);

        update = true;
    }

    if (update) {
        display.display();
    }
}

void drawCourt() {
    display.drawRect(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, WHITE);
}

// Функция перезапуска игры
void resetGame() {
    // Сброс координат мяча в центр
    ball_x = 64;
    ball_y = 16;

    // Случайное направление старта (или фиксированное)
    ball_dir_x = 1; 
    ball_dir_y = 1;

    // Перерисовка игрового поля
    display.clearDisplay();
    drawCourt();

    // Возвращаемся в начало следующего кадра
    ball_update = millis();
    paddle_update = ball_update;
}
```

### Основные изменения:
1.  Добавлены константы `RESET_BUTTON_PIN` и `RESET_DEBOUNCE_TIME`.
2.  Добавлена функция `resetGame()`, которая сбрасывает все переменные мяча и чистит экран.
3.  Внутри `loop` добавлена проверка `if (digitalRead(...) == LOW)`, которая вызывает эту функцию.
4.  Используется дебаунсинг (проверка интервала `LAST_RESET`), чтобы при долгом удержании кнопки она не "кликала" каждые 10 мс.

