### C++ Code Snippet (Sequential Control)
Save this file as `motors.c++`. Note that we use the **WiringPi** library because it abstracts Linux GPIO operations into readable functions.

**Warning:** Run this code using `sudo ./motors` because it needs root access to change GPIO settings. Ensure your motors have a 9V or 12V battery pack connected to the L298N `VIN`, not the Pi's 5V output.

```cpp
#include <iostream>       // Include standard input/output stream library for printing messages
#include <wiringPi.h>     // Include the WiringPi library for managing hardware pins (GPIO)
#include <unistd.h>       // Include standard Unix utility definitions for system calls (like sleep)

// -----------------------------------------------------------------------------
// Configuration Constants
// These represent the physical location of your wires on the L298N and the Raspberry Pi.
// YOU MUST MATCH THESE TO YOUR PHYSICAL WIRING DIAGRAM.
// -----------------------------------------------------------------------------
#define PIN_IN1  0   // Raspberry Pi GPIO Pin 0 wired to L298N Motor A Input 1 (Direction)
#define PIN_IN2  1   // Raspberry Pi GPIO Pin 1 wired to L298N Motor A Input 2 (Direction)
#define PIN_ENA  2   // Raspberry Pi GPIO Pin 2 wired to L298N Motor A Enable (Power Switch)
#define PIN_IN3  3   // Raspberry Pi GPIO Pin 3 wired to L298N Motor B Input 1 (Direction)
#define PIN_IN4  4   // Raspberry Pi GPIO Pin 4 wired to L298N Motor B Input 2 (Direction)
#define PIN_ENB  5   // Raspberry Pi GPIO Pin 5 wired to L298N Motor B Enable (Power Switch)

int main() { 
    // -----------------------------------------------------------------------------
    // 1. Initialize Hardware Settings
    // -----------------------------------------------------------------------------
    // WiringPi initializes the internal chip registers to track which pins are used.
    if (wiringPiSetup() == -1) { 
        // If this returns -1, the setup failed (likely wrong permissions or hardware).
        std::cout << "Error: Could not initialize WiringPi system." << std::endl; 
        return 1; // Return code 1 indicates failure to operating system.
    } 

    std::cout << "--- System Initialized ---" << std::endl;
    std::cout << "Setting all motor pins as Outputs (DIGITAL_WRITE mode)." << std::endl;

    // -----------------------------------------------------------------------------
    // 2. Configure Motor A (First Motor)
    // -----------------------------------------------------------------------------
    // By default, wiringPi treats pins as INPUTS. We force them to OUTPUTS so we can control them.
    pinMode(PIN_ENA, OUTPUT); // Set Pin ENA to Output so we can send power signal.
    digitalWrite(PIN_ENA, HIGH); // Send Logic '1' (HIGH) to Enable Motor A. 
    // Note: L298N expects HIGH voltage on 'ENA' to allow current flow to the motor.

    // Set Direction Pins for Motor A. We start with both directions defined.
    // Currently, this will depend on previous states or reset to OFF state.
    digitalWrite(PIN_IN1, LOW);  // Set Input 1 to LOW (Ground).
    digitalWrite(PIN_IN2, HIGH); // Set Input 2 to HIGH (Battery Voltage).
    // Logic Explanation: 
    //  In1=0, In2=1 creates a specific polarity across the bridge.
    //  Depending on your wiring diagram, this specific combination might spin Clockwise.
    //  The important rule is that they are DIFFERENT values (Low vs High).

    // -----------------------------------------------------------------------------
    // 3. Test Motor A Movement (Sequential Step)
    // -----------------------------------------------------------------------------
    std::cout << "Step 1: Starting Motor A (Forward)" << std::endl;

    // Sleep is NOT a loop. It simply pauses the CPU execution for 2 seconds.
    usleep(2000000); // Wait 2 million microseconds = 2 Seconds.
    // This allows the motor time to physically rotate before we change settings.

    // Now, reverse Motor A.
    std::cout << "Step 2: Reversing Motor A" << std::endl;
    digitalWrite(PIN_IN1, HIGH); // Swap direction: Input 1 is now HIGH.
    digitalWrite(PIN_IN2, LOW);  // Swap direction: Input 2 is now LOW.
    // Remember: L298N Direction bridges swap the magnetic polarity when High/Low positions swap.

    usleep(2000000); // Wait another 2 seconds for reversal action.

    // -----------------------------------------------------------------------------
    // 4. Stop Motor A
    // -----------------------------------------------------------------------------
    std::cout << "Step 3: Stopping Motor A" << std::endl;
    // To safely stop the motor on L298N, you cut power to the Motor Coil.
    // We turn the Enable pin (ENA) to LOW.
    digitalWrite(PIN_ENA, LOW); 
    // Now no current flows from VIN through the bridge to the motor shaft.

    // -----------------------------------------------------------------------------
    // 5. Configure Motor B (Second Motor)
    // -----------------------------------------------------------------------------
    // Resetting pins to default states ensures safety before enabling new motor.
    digitalWrite(PIN_IN3, LOW); // Set Input 3 Low.
    digitalWrite(PIN_IN4, HIGH);// Set Input 4 High.
    // Note: The "direction" logic (In3 != In4) must hold true to move.
    digitalWrite(PIN_ENB, HIGH); // Enable Motor B channel. Allow battery power to connect.

    std::cout << "Step 4: Starting Motor B" << std::endl;

    // Ensure Motor B is spinning for a few moments.
    usleep(2000000); // Wait 2 Seconds.

    // -----------------------------------------------------------------------------
    // 6. Stop Motor B (Cleanup)
    // -----------------------------------------------------------------------------
    std::cout << "Step 5: Stopping Motor B" << std::endl;
    digitalWrite(PIN_ENB, LOW); // Cut power to Motor B coil to stop movement.

    // -----------------------------------------------------------------------------
    // 7. Exit Program
    // -----------------------------------------------------------------------------
    std::cout << "--- Execution Complete ---" << std::endl;
    wiringPiCleanup(); // Good practice to release GPIO resources back to the OS.
    return 0;          // Return code 0 indicates success to operating system.
}
```

