    }

    // New time base with 47 points from 0 to n - 1
    int m = 47;
    std::vector<double> x_new(m);
    double step = (n - 1.0) / (m - 1);
    for (int i = 0; i < m; ++i) {
        x_new[i] = i * step;
    }

    // Perform interpolation
    std::vector<double> y_interpolated(m);
    for (int i = 0; i < m; ++i) {
        double x = x_new[i];
        int idx = static_cast<int>(std::floor(x));
        double frac = x - static_cast<double>(idx);

        if (frac == 0.0) {
            y_interpolated[i] = y[idx];
        } else if (idx < 0 || idx >= n - 1) {
