## 💻 Solution Code (`main.cpp`)

```cpp
#include <QApplication>
#include <QDebug>
#include <QFile>
#include <QBuffer>
#include <QString>
#include <QByteArray>
#include <QTemporaryFile>
#include "qxlsx.h"

struct CellValue {
    int originalRow;
    QString originalValue;
    long long parsedValue;
    bool isNumber = false;
    bool isValidFormat = false;
};

class ExcelValidator {
public:
    static std::vector<CellValue> readExcelFile(const QString& filePath);

    static long long parseFormattedNumber(const QString& str, base_t &type);

    static bool isAllowed(long long val, const std::set<long long>& allowed);

private:
    enum base_t { DEC, HEX, OCT, BIN };
};

std::vector<CellValue> ExcelValidator::readExcelFile(const QString& filePath) {
    std::vector<CellValue> result;
    QFile file(filePath);

    if (!file.open(QIODevice::ReadOnly)) {
        qCritical() << "Error opening file:" << filePath;
        return result;
    }

    QByteArray data = file.readAll();
    file.close();

    // Create temporary buffer
    QBuffer buf(&data);
    buf.open(QIODevice::ReadOnly);

    try {
        qxlsp::workbook workbook;
        workbook.load(buf);

        auto sheets = workbook.sheets();
        if (sheets.empty()) {
            qWarning() << "No sheets found";
            return result;
        }

        for (int row = 0; row < sheets[0].rowCount(); ++row) {
            for (int col = 0; col < sheets[0].columnCount(); ++col) {
                auto cell = sheets[0].cell(row, col);
                if (cell.isNumeric()) {
                    CellValue cv;
                    cv.originalRow = row + 1;
                    cv.originalValue = QString::number(cell.valueAsDouble());
                    cv.parsedValue = cell.valueAsInt();
                    cv.isValidFormat = true;
                    cv.isNumber = true;
                    result.push_back(cv);
                }
            }
        }
    } catch (...) {
        qCritical() << "Failed to parse Excel data";
        return result;
    }

    return result;
}

long long ExcelValidator::parseFormattedNumber(const QString& str, base_t &type) {
    type = DEC;
    if (str.startsWith("0x", Qt::CaseInsensitive)) {
        type = HEX;
        return std::stoll(str.mid(2), nullptr, 16);
    } else if (str.startsWith("0o", Qt::CaseInsensitive)) {
        type = OCT;
        return std::stoll(str.mid(2), nullptr, 8);
    } else if (str.startsWith("0b", Qt::CaseInsensitive)) {
        type = BIN;
        return std::stoll(str.mid(2), nullptr, 2);
    } else {
        return std::stoll(str.trimmed().toStdString(), nullptr, 10);
    }
}

bool ExcelValidator::isAllowed(long long val, const std::set<long long>& allowed) {
    return allowed.find(val) != allowed.end();
}

void printResult(bool isValid, const CellValue& cell, const std::set<long long>& allowed) {
    qInfo() << "=== Result ===";
    qInfo() << "Original Value:" << cell.originalValue;
    qInfo() << "Parsed Value:" << cell.parsedValue;
