<script>
    // --- Application State ---
    const files = JSON.parse(localStorage.getItem('devNote_files')) || [];
    let activeTabId = null;
    let currentTheme = 'dark';
    let searchMode = false;

    // --- DOM Elements ---
    const tabsContainer = document.getElementById('tabsList');
    const inputEl = document.getElementById('editorInput');
    const displayEl = document.getElementById('codeDisplay');
    const lineNumbersEl = document.getElementById('lineNumbers');
    const fileNameSpan = document.getElementById('fileName');
    const cursorPosSpan = document.getElementById('cursorPos');

    // --- Initialization ---
    function init() {
        loadTabs();
        updateCursorInfo();

        // Event Listeners
        inputEl.addEventListener('input', () => {
            highlightCode();
            saveToLocal();
            updateCursorInfo();
        });

        inputEl.addEventListener('keyup', updateCursorInfo);
        inputEl.addEventListener('scroll', syncScroll);

        // Theme Toggle
        document.getElementById('themeToggle').addEventListener('click', () => {
            currentTheme = currentTheme === 'dark' ? 'light' : 'dark';
            document.body.setAttribute('data-theme', currentTheme);
            localStorage.setItem('devNote_theme', currentTheme);
        });

        // Auto-save check every 30s
        setInterval(saveToLocal, 30000);

        // Restore active state
        if(activeTabId && files.find(f => f.id === activeTabId)) {
            renderFileContent(activeTabId);
        } else {
            createNewFile();
        }
    }

    // --- Core Logic: Tabs ---
    function loadTabs() {
        if(files.length === 0) return;
        tabsContainer.innerHTML = '';
        files.forEach(file => {
            const div = document.createElement('div');
            div.className = `file-tab ${file.id === activeTabId ? 'active' : ''}`;
            div.onclick = (e) => openTab(file.id, e);
            div.innerHTML = `
                <span>${getIcon(file.type)} ${escapeHtml(file.name)}</span>
                <span class="close-tab">&times;</span>
            `;
            // Close logic handled inline for simplicity
            setTimeout(() => {
                div.querySelector('.close-tab').onclick = () => removeTab(file.id);
            }, 0);
            tabsContainer.appendChild(div);
        });
    }

    function createNewFile() {
        const id = Date.now().toString();
        const name = prompt("Enter file name:", `untitled_${files.length + 1}.txt`);
        if (!name) return;

        const fileType = getFileType(name.split('.').pop());
        const newFile = {
            id: id,
            name: name,
            type: fileType,
            content: '',
            lastSaved: Date.now()
        };

        files.push(newFile);
        files.sort((a,b) => b.lastSaved - a.lastSaved);
        localStorage.setItem('devNote_files', JSON.stringify(files));

        loadTabs();
        openTab(id);
    }

    function openTab(id, event) {
        if(event) event.stopPropagation(); // Prevent bubbling

        activeTabId = id;
        const file = files.find(f => f.id === id);

        renderFileContent(file);
        loadTabs();

        // Focus input after render
        setTimeout(() => {
            inputEl.focus();
            if(window.getSelection().toString()) window.getSelection().removeAllRanges();
        }, 10);
    }

    function removeTab(id) {
        if(confirm("Close this file? Unsaved changes will be lost.")) {
            files.splice(files.findIndex(f => f.id === id), 1);
            saveState();

            if (files.length > 0) {
                activeTabId = files[files.length - 1].id;
                renderFileContent(files.find(f => f.id === activeTabId));
                loadTabs();
            } else {
                activeTabId = null;
                inputEl.value = "";
                displayEl.textContent = "";
                lineNumbersEl.innerHTML = "";
                fileNameSpan.textContent = "No Open Files";
            }
        }
    }

    function renderFileContent(file) {
        fileNameSpan.textContent = `${getIcon(file.type)} ${file.name}`;
        inputEl.value = file.content;
        syncScroll();
        highlightCode();
    }

    // --- Core Logic: Syntax Highlighting ---
    function highlightCode() {
        const code = inputEl.value;

        // Handle search mode if active
        let processedCode = code;
        if(searchMode) {
            const searchTerm = document.getElementById('searchText').value;
            if(searchTerm) {
                const regex = new RegExp(`(${escapeRegExp(searchTerm)})`, 'gi');
                processedCode = code.replace(regex, '<mark class="search-hit">$1</mark>');
            }
        }

        // Use Prism to highlight
        if(prism.plugins.autoloader) {
             // If autoloader is active, we can wait a bit or try direct
        }

        // Simple manual escape to prevent HTML injection before highlighting
        const safeCode = `<pre class="lang-${getFileLanguage(file.getExtension())}">${escapeHtml(processedCode)}</pre><code>${escapeHtml(processedCode)}</code>`;

        // This is a simplified version. Prism works best when fed raw text through its parser.
        // Since we are overlaying textareas, we write directly to code element.
        // Note: In a production app, a diff algorithm is better than full re-render on keystroke.

        displayEl.innerHTML = '';
        try {
            Prism.highlightElement(displayEl); // This relies on the innerHTML structure being prepped correctly

            // Re-inject for the single-line text method
            displayEl.innerHTML = `<code class="language-${getFileLanguage(file.getExtension())}">${escapeHtml(processedCode)}</code>`;
            Prism.highlightElement(displayEl);
        } catch(e) { console.error("Highlight error", e); }
    }

    function syncScroll() {
        const val = inputEl.scrollTop;
        displayEl.scrollTop = val;
        lineNumbersEl.scrollTop = val;
    }

    function updateCursorInfo() {
        const pos = inputEl.selectionStart;
        const line = inputEl.value.substr(0, pos).split('\n').length;
        cursorPosSpan.innerText = `Ln ${line}, Col ${pos % 20 == 0 ? 0 : (pos%20)}`;

        if(lineNumbersEl.children.length < line) {
            lineNumbersEl.innerHTML += `<div>${line}</div>`;
