            # Initialize Source
            source = self._source if self._source else iter([])

            # Build rich console
            if progress_bar:
                with Progress(
                    SpinnerColumn(),
                    TextColumn("[bold blue]{task.name}"),
                    BarColumn(),
                    TimeElapsedColumn(),
                ) as progress:
                    total_tasks = len(self.steps)

                    for i, step in enumerate(self.steps):
                        task_id = f"Step-{i}"
                        progress.add_task(task_id, visible=False)

                        # Stream processing
                        stream = self._map_stream(source, step, task_id)
                        source = stream

            else:
                temp_source = source
                for step in self.steps:
                    temp_source = self._map_stream(temp_source, step, "")

            # Finalization
            print("Pipeline Complete.")

        asyncio.run(_loop())
