    config = RerankConfig.parse()

    # 2. Define Chain
    chain = (Chain(config)
             .load("data/queries.txt")
             .take(config.n)
             .map(search_exa, use_cache=True)       # Parallelized Search
             .flatten()                              # Flatten lists of 5
             .save("data/exa_results.json")          # Dump 1

             # NOTE: Groupby consumes the EXACT stream. 
             # In the previous step we dumped to JSON. We need to reload for this to work seamlessly.
             # Ideally .load("data/exa_results.json") here.
