        // 注意：根据你的需求描述：左 -> +60，右 -> -60。请确认引擎坐标系
        targetX = targetX + 60; 
    }
    else if (dir == ENUM_DIRECTION_RIGHT)
    {
        // 方向向右时，目标点在左侧
        targetX = targetX - 60;
    }

    // 更新角色朝向以匹配移动意图
    sq_SetCurrentDirection(obj, dir);

    // 平滑移动到新位置
    // 如果 obj.setCurrentPos 内部有自动平滑，直接使用即可。
    // 如果需要手动帧率平滑，可参考下方 sq_GetUniformVelocity 用法
    obj.setCurrentPos(targetX, targetY, targetZ);

    // --- 旧代码中的通用移动被移除 (sq_moveWithParent)，因为会被setCurrentPos覆盖 ---

    if (SERVERNTLANCE_A == 3)
    {
        obj.sendStateOnlyPacket(12);
        obj.flushSetStatePacket();
    }

    break;
```

### 补充说明：关于平滑移动的进阶实现

如果你发现直接 `setCurrentPos` 不够平滑，或者需要在客户端/本地做更精细的物理插值，可以在主循环（如 `update` 或 `tick` 中，而不是在 `case` 里）结合你提供的 `sq_GetUniformVelocity` 写法来更新位置。例如：

```squirrel
// 放在 update 循环或专门的移动更新函数中
if (state == CASE_MOVE_TARGET) {
    local totalT = calcTotalTime(startT, finishT);
    local currentT = elapsedTime();
    local progress = min(currentT / totalT, 1.0); // 避免超出范围

    // 均匀速度插值公式 (简化版)
    local dx = startPos - targetPos.x; 
    local dy = startPos - targetPos.y;
    local dz = startPos - targetPos.z;

    // 调用你提供的工具函数，传入起点距离和剩余时间
    // local moveVel = sq_GetUniformVelocity(dx, dy, dz, currentT, totalDuration); 

    // obj.addMoveDelta(moveVel); 
}
```

**注意：**
1.  **坐标系统**：你的需求中写的是 `父角色 Left -> X+60`，`父角色 Right -> X-60`。在某些 3D 引擎中，向左可能是 `-60`（取决于相机朝向）。请务必测试实际效果是否符合预期。
2.  **枚举常量**：确保 `ENUM_DIRECTION_LEFT` 和 `ENUM_DIRECTION_RIGHT` 在当前作用域内是可访问的常量。
3.  **父角色跟随**：虽然设置了 `setMapFollowParent`，但在移动过程中，物理位移是以 `setCurrentPos` 为准的。建议确认该框架是否允许“父级跟随”和“独立移动坐标”同时存在，否则可能会导致物理碰撞抖动。

Here is a complete, standalone solution. It includes the HTML structure, JavaScript logic, and CSS styling all packed into a Single Custom Element definition.

You can save this as an `.html` file to test it immediately, or include the script and styles in your application.

### The Implementation (`x-details.js`)

```javascript
/**
 * X-Details Web Component
 * A details-like component where the 'intro' is always visible
 */
class XDetails extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });

    // Internal template strings
    this.template = `
      <style>
        :host {
          display: block;
          width: 100%;
          --xd-color-primary: #333;
          --xd-color-border: #ddd;
          --xd-icon-bg: #f0f0f0;
        }

        .wrapper {
          border: 1px solid var(--xd-color-border);
          border-radius: 4px;
          overflow: hidden;
          background: white;
        }

        /* Header Section */
        .header-row {
          display: flex;
          align-items: center;
          padding: 1rem;
          cursor: pointer;
          background: #fafafa;
          transition: background 0.2s;
        }

        .header-row:hover {
          background: #f5f5f5;
        }

        /* Icon Container (The Square) */
        .icon-square {
          display: flex;
          justify-content: center;
          align-items: center;
          width: 24px;
          height: 24px;
          margin-right: 12px;
          font-size: 14px;
          font-weight: bold;
          color: var(--xd-color-primary);
          background-color: var(--xd-icon-bg);
          border-radius: 4px;
          user-select: none;
          transition: transform 0.3s ease;
        }

        /* Header Text */
        .header-title {
          font-size: 1.1rem; /* Slightly larger font */
          font-weight: 600;
          border-bottom: 1px solid transparent; /* Hidden by default, shown when open if desired */
        }

        /* Expand Button - Visible ONLY when collapsed */
        .expand-btn {
          margin-left: auto; /* Pushes to right */
          font-size: 0.9rem;
          color: #666;
          text-transform: uppercase;
          letter-spacing: 0.5px;
          transition: opacity 0.3s ease;
        }

        /* Intro Section (Always Visible) */
        .intro-section {
          padding: 0 1rem 1rem 1rem;
          font-size: 0.95rem;
          line-height: 1.5;
          color: #555;
          display: block;
          animation: fadeIn 0.3s ease;
        }

        /* Details Section (Initially Hidden) */
        .details-section {
          padding: 1rem;
          display: none; /* Toggled via JS */
          animation: slideDown 0.3s ease-out forwards;
        }

        .details-section.show {
          display: block;
        }

        /* Utility Animations */
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        @keyframes slideDown {
          from { opacity: 0; margin-top: 5px; }
          to { opacity: 1; margin-top: 0; }
        }

        /* Active State (When Open) */
        :host([open]) {
           /* No host-level style changes required, handled by child classes mostly */
        }

        :host([open]) .icon-square {
          transform: rotate(45deg); /* Spin the square */
        }

        :host([open]) .expand-btn {
          opacity: 0;
          pointer-events: none;
        }
      </style>

      <div class="wrapper">
        <!-- Click Area: Contains Icon & Header Title -->
        <div 
          class="header-row" 
          role="button" 
          tabindex="0"
          onclick="this.closest('x-details').toggle()"
          onkeydown="if(event.key === 'Enter' || event.key === ' ') this.closest('x-details').toggle()"
        >
          <div class="icon-square">+</div>
          <slot name="header"></slot>
          <span class="expand-btn">Expand More</span>
        </div>

        <!-- Intro: Always Visible -->
        <div class="intro-section">
          <slot name="intro"></slot>
        </div>

        <!-- Details: Only Visible when expanded -->
        <div class="details-section">
          <slot name="details"></slot>
        </div>
      </div>
    `;

    this.render();
  }

  render() {
    this.shadowRoot.innerHTML = this.template;
    // Initial state ensures content is hidden if no slot exists
    this.shadowRoot.querySelector('.details-section').classList.remove('show');
  }

  /**
   * Toggles the open/closed state
   */
  toggle() {
    const isOpen = this.hasAttribute('open');
    if (isOpen) {
      this.removeAttribute('open');
    } else {
      this.setAttribute('open', '');
    }
  }

  connectedCallback() {
    // Expose toggle method to outside world if needed
    this.toggle = () => this.toggle.bind(this)();
  }
}

// Register the custom element
customElements.define('x-details', XDetails);
```

