            avg_scores_calc [label="Compute Mean & Std Dev\nof Scores", shape=box, fillcolor="#118ab2", style=filled];
            best_model_pick [label="Select Best Parameters\n& Retraining", shape=octagon, fillcolor="#000000", style=filled, fontcolor=white];
            output_result [label="Optimal Hyperparameters\n& Best Model", shape=ellipse, fillcolor="#000000", style=filled, fontcolor=white, width=3, height=1.5];
        }

        // --- Connections & Control Flow ---
        // Init Path
        input_data -> preprocess -> data_splitter -> hp_combinations;

        // HP Loop Entry Point -> Fold Loop
        hp_combinations -> fold_train_test_pair;
        fold_train_test_pair -> model_training -> model_evaluate -> fold_score_update -> fold_complete;

        // Feedback Loop for K-Folds (Dotted line to indicate repetition)
        fold_score_update -> fold_complete;
        fold_complete -> fold_train_test_pair [label="", style=dashed, constraint=false, color=red];

        // Fold Loop Exit -> Score Handling
        fold_score_update -> score_accumulator [style=invis]; // Abstracting direct link

        // Explicit path from Fold completion to Accumulator
        fold_complete -> hp_combinations [label="Loop Ends?", style=dashed, penwidth=2];
        hp_combinations -> score_accumulator;

        // Accumulator -> Calculations
        score_accumulator -> avg_scores_calc -> best_model_pick -> output_result;

        // Return to start for next HP Combination (Visual loop)
        hp_combinations -> fold_train_test_pair [style=dashed, constraint=false, color=blue];

        // Visualizing the K-folds loop exit back to the start of HP search isn't ideal in strict linear flow,
        // so we draw an arrow from Fold Completion to HP accumulator to show control return.
        fold_complete -> hp_combinations [label="Continue HP Search", style=dashed];
    }
}
```

### Explanation of the Diagram Design

1.  **Hierarchical Clusters**: The diagram uses `subgraph cluster_X` blocks to clearly separate phases (Initialization, HP Search, Folding, Selection). This prevents visual clutter while maintaining structure.
2.  **Color Coding**:
    *   **Blue (Init)**: Represents raw data preparation.
    *   **Purple (HP)**: Highlights where hyperparameter variations occur.
    *   **Pink/Orange (Folding)**: Specifically denotes the mechanical act of splitting and retraining data.
    *   **Green (Train) & Red (Eval)**: Contrasts the generation of weights vs. testing them.
    *   **Black (Result)**: Signifies the final optimized outcome.
3.  **Feedback Loops**: Dashed arrows indicate loops (where the model retrains on different folds or different hyperparameter sets) without drawing complex cycles that confuse the layout.
4.  **Shapes**:
    *   **Ellipse**: Start/End points.
    *   **Hexagon/Octagon**: Critical decision or result nodes.
    *   **Diamond**: Decision logic.
5.  **Workflow**: The flow goes from Top-to-Bottom (`rankdir=TB`). It starts with Data Prep $\rightarrow$ Hyperparameter definition $\rightarrow$ Nested Loops (HP $\to$ K-Folds) $\rightarrow$ Aggregation $\rightarrow$ Best Result.

