#### `RecordViewModel.swift`
The ViewModel observes the Service, tracks state, and communicates with UI.

```swift
import Foundation
import SwiftUI

@MainActor
class RecordViewModel: ObservableObject {
    // MARK: - Published State
    @Published var isRecording: Bool = false
    @Published var errorMessage: String?
    @Published var durationText: String = "00:00"
    @Published var progressPercentage: Float = 0.0

    // MARK: - Private Properties
    private let audioService = AudioEngineService.shared
    private var timer: Timer?
    private var savedUrl: URL?

    // MARK: - Initial Load
    init() {
        checkPermissions()
    }

    // MARK: - Actions
    func toggleRecording() {
        guard let savedUrl = savedUrl else {
            // 1. Starting New Recording
            startTimer()
            startEngine()
            startRecording()
            return
        }

        // 2. Stopping Existing Recording
        stopEngine()
        stopTimer()
        finishRecording()
    }

    private func startRecording() {
        do {
            // Create a unique filename with timestamp
            let date = Date()
            let fileName = "Recording_\(date.timeIntervalSince1970).m4a"
            let fileManager = FileManager.default
            let documentsPath = fileManager.urls(for: .documentDirectory, in: .userDomainMask)[0]
            let destinationUrl = documentsPath.appendingPathComponent(fileName)

            audioService.startRecording(url: destinationUrl) { result in
                switch result {
                case .success(let url):
                    self.savedUrl = url
                    self.errorMessage = nil
                    DispatchQueue.main.async {
                        self.isRecording = true
                    }
                case .failure(let error):
                    self.errorMessage = "Failed to start recording: \(error.localizedDescription)"
                    self.isRecording = false
                }
            }
        } catch {
            errorMessage = "Permission Denied"
        }
    }

    private func finishRecording() {
        audioService.stopRecording()
        // Optional: Playback preview
        dismissKeyboardIfNeeded()
        // Move file to Documents or share
        DispatchQueue.main.async { [weak self] in
            self?.isRecording = false
            // Update stats could go here
        }
    }

    private func startTimer() {
        timer = Timer.scheduledTimer(withTimeInterval: 1.0, repeats: true) { [weak self] _ in
            Task { @MainActor in
                self?.durationText = Date().timeIntervalSince(self?.audioService.totalDurationInSeconds ?? 0).formatted(timeStyle: .short)
            }
        }
        RunLoop.current.add(timer, forMode: .common)
    }

    private func stopTimer() {
        timer?.invalidate()
        timer = nil
    }

    private func startEngine() {
        audioService.isRunning = true
        // Note: Actual recording happens via AVAudioRecorder, 
        // Visualization happens via AVAudioEngine in shared service.
    }

    private func stopEngine() {
        audioService.isRunning = false
    }

    // MARK: - Permissions
    private func checkPermissions() {
        if AVAudioSession.sharedInstance().getCategoryOptions(nil: .defaultCategory, &options: nil) != nil {
             // Standard flow
        }
    }
}

