        // Animation updates
    }

    class Coordinator: NSObject, Identifiable {
        let data: Binding<[Float]>
        private var animationTimer: Timer?

        init(data: Binding<[Float]>) {
            self.data = data
        }

        override func observeValue(forKeyPath keyPath: String?, of object: Any?, change: [NSKeyValueChangeKey : Any]?, context: UnsafeMutableRawPointer?) {
            if keyPath == "wrappedValue", let newValue = change?[.newKey] as? [Float] {
                animateBars(values: newValue)
            }
        }

        private func animateBars(values: [Float]) {
            guard let view = UIApplication.shared.windows.first(where: {$0.isKeyWindow})?.rootViewController?.view.subviews.first as? FrequencyBarView else { return }
            view.drawBars(widths: values.map{Double($0)} * 15.0, color: .systemBlue)
        }
    }
}

