struct ColorViewInner: View {
    enum Type { case standby, recording }
    var type: Type

    var body: some View {
        GeometryReader { geo in
            ForEach(0..<20) { i in
                RoundedRectangle(cornerRadius: 2)
                    .fill(colorForIndex(i, isRec: type == .recording))
                    .frame(width: geo.size.width / 20, height: CGFloat(geo.size.height / 50) * CGFloat(max(0.0, Double(i) % 10)))
            }
        }
        .background(Color.black.opacity(0.5))
        .cornerRadius(20)
    }

    func colorForIndex(_ i: Int, isRec: Bool) -> Color {
        if isRec {
            return Color(red: Double(i) / 20, green: Double(i) / 20, blue: 1.0)
        }
        return Color.green.opacity(Double(i) / 20)
    }
}
