    const self = this;

    // Note: In Pure JS plugins, handling data flow requires the plugin to 
    // update its own geometry/font manually when config changes.

    // Listen for changes from the external ConfigDialog
    // Since SimpleWidget doesn't auto-bind to exposed variables in older plasma,
    // we need to manually update.
    const listener = this.engine.rootSettingsGroup().addObserver("SimpleW", "fontSize", this.updateFont, this);
};

MyWidget.prototype.updateFont = function(group, key, value) {
