// Initialization
SimpleWWidget.prototype.init = function() {
    KPlugin.Scripted.Applet.prototype.init.call(this);

    const settings = this.engine.rootSettingsGroup("SimpleWSettings");
    this.fontSize = settings.readEntry("fontSize", 48);

    // Request focus on mouse hover for better visibility
    this.focusPolicy = Qt.FocusPolicy.StrongFocus;

    // Create a graphic item to hold the text
    // In pure JS without C++, we rely on QML or Canvas
    // We use a standard View.
    this.view = new QGraphicsView();
    this.view.setFixedSize(60, 60);
    this.view.setMouseTracking(true);
    this.addSubWidget(this.view);
};

// Timer loop
SimpleWWidget.prototype.timerEvent = function(evt) {
    this.draw();
};

SimpleWWidget.prototype.draw = function() {
    const ctx = this.view.context2d;
    if(!ctx) return;

    // Reset styles
    ctx.clearRect(0, 0, 60, 60);
    ctx.strokeStyle = "#000000";
    ctx.lineWidth = 3;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.font = `${this.fontSize}px Serif`;

    // Draw Stroke then Fill
    ctx.strokeText("W", 30, 30);
    ctx.fillText("W", 30, 30);
};
