  text,
  onExpandToggle,
  maxLines = 1,
  seeMoreLabel = 'See more',
  seeLessLabel = 'See less',
  containerStyle,
  textStyle,
  disabled = false,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showIndicator, setShowIndicator] = useState(false);

  // Detect if content exceeds limit using heuristics + visual check
  // We simulate a layout check by calculating width relative to container
  useEffect(() => {
    if (disabled || isExpanded) {
      setShowIndicator(false);
      return;
