    // Basic heuristic: If text is very long, it's likely multiline
    // Ideally, you'd use a hidden ScrollView to measure exact height
    const needsExpansion = text.trim().length > HEURISTIC_THRESHOLD || text.includes('\n');

    // Refined check: If text exceeds 1 line at 16px font (approx)
    // This keeps the bundle light while being functional
    setShowIndicator(needsExpansion);
