homeassistant-cluster/
├── cue.mod.yaml
├── main.cue
├── vars.cue              # Shared constants (Namespaces, Versions, Secrets)
├── services/             # Generic Kubernetes Service logic
│   └── k8s-service.cue
├── apps/                 # Workload Definitions
