Here's a robust and flexible JavaScript `Events` class that implements the Observer pattern. It supports subscribing and unsubscribing callbacks to named events and triggers those events with optional arguments.

```javascript
class Events {
  constructor() {
    this._events = new Map();
  }

  /**
   * Subscribe a callback to a specific event name
   * @param {string} eventName - The name of the event
   * @param {Function} callback - The function to execute on event trigger
   */
  subscribe(eventName, callback) {
    if (typeof callback !== 'function') {
      throw new TypeError('Callback must be a function');
    }
    if (typeof eventName !== 'string' || !eventName.trim()) {
      throw new TypeError('Event name must be a non-empty string');
    }

    const subscribers = this._events.get(eventName) || [];
    subscribers.push(callback);
    this._events.set(eventName, subscribers);
    return this;
  }

  /**
   * Unsubscribe a previously registered callback from a specific event
   * @param {string} eventName - The name of the event
   * @param {Function} callback - The callback to remove
   */
  unsubscribe(eventName, callback) {
    if (typeof eventName !== 'string' || !eventName.trim()) {
      throw new TypeError('Event name must be a non-empty string');
    }
    if (typeof callback !== 'function') {
      throw new TypeError('Callback must be a function');
    }

    const subscribers = this._events.get(eventName);
    if (!subscribers) return this;

    const index = subscribers.indexOf(callback);
    if (index !== -1) {
      subscribers.splice(index, 1);
    }

    if (subscribers.length === 0) {
      this._events.delete(eventName);
    }

    return this;
  }

  /**
   * Trigger one or more events with optional parameters
   * Supports both array-style or individual event arguments
   * @param {...*} args - Event names (strings) or options to pass to callbacks
   */
  trigger(...args) {
    const firstArg = args[0];
    const eventNames = Array.isArray(firstArg) ? firstArg : [firstArg];

    eventNames.forEach(eventName => {
      const options = args.slice(1);
      this._dispatchEvent(eventName, ...options);
    });

    return this;
  }

  /**
   * Internal method to safely dispatch an event to all its listeners
   * @private
   */
  _dispatchEvent(eventName, ...options) {
    const subscribers = this._events.get(eventName);
    if (!subscribers || subscribers.length === 0) return;

    const callbacks = [...subscribers];

    for (const callback of callbacks) {
      try {
        callback(...options);
      } catch (error) {
        console.warn(`❌ Error in subscriber for event "${eventName}":`, error);
      }
    }
  }

  /**
   * Check if any listener is subscribed to a given event
   * @param {string} eventName
   * @returns {boolean}
   */
  hasListener(eventName) {
    return this._events.has(eventName) && this._events.get(eventName).length > 0;
  }

  /**
   * Get count of active listeners for a specific event
   * @param {string} eventName
   * @returns {number}
   */
  listenerCount(eventName) {
    return this._events.get(eventName)?.length || 0;
  }

  /**
   * List all subscribed events and their listener counts
   * @returns {Object}
   */
  getListenersSummary() {
    const summary = {};
    for (const [event, callbacks] of this._events) {
      summary[event] = callbacks.length;
    }
    return summary;
  }

  /**
   * Clear all event subscriptions
   */
  clearAll() {
    this._events.clear();
  }
}
```

### Key Features

- **Robust Input Validation**: Ensures valid event names and callbacks before subscribing.
- **Flexible Triggering**: Accepts either a single event name or an array.
- **Safe Callback Execution**: Prevents crashes due to errors in one subscriber.
- **Additional Utilities**: Includes methods to check listeners, summarize events, and clear subscriptions.

### Example Usage

```javascript
const events = new Events();

// Subscribe
events.subscribe('dataLoaded', (message) => {
  console.log('Data loaded:', message);
});

events.subscribe('userLoggedIn', () => {
  console.log('User logged in!');
});

// Unsubscribe
// events.unsubscribe('dataLoaded', (message) => { /*...*/ });

// Trigger with data
events.trigger('dataLoaded', { id: 42 });
events.trigger(['dataLoaded', 'userLoggedIn'], 'Hello, World!');

// Utilization examples
console.log(events.hasListener('dataLoaded'));          // true
console.log(events.listenerCount('dataLoaded'));        // 1
console.log(events.getListenersSummary());              // { 'dataLoaded': 1, 'userLoggedIn': 1 }
events.clearAll();                                      // Clears all listeners
```

