1.  **Inject CSS Styles**: Add a class for the highlighting (e.g., `.quote-highlight`) with a red color.
2.  **Modify the Rendering Logic**: After `marked` generates the HTML and `DOMPurify` sanitizes it, traverse the DOM tree to find text nodes containing quotes. We must ensure we skip code blocks (to avoid confusing syntax inside `<code>` tags) and wrap the quoted content in a span with the new CSS class.

Since `MarkdownBlock` and `MarkdownSpan` both inherit from `MarkdownElement` and share the `render` lifecycle, implementing this in the `MarkdownElement` base class ensures both custom elements behave correctly.

Here is the updated code:

```javascript
/**
 * <md-block> custom element
 * @author Lea Verou
 * V https://github.com/LeaVerou/md-block/commit/25149d54b93e25f2e30810aabaaa46a58b8bda50
 */

let marked = window.marked;
let DOMPurify = window.DOMPurify;
let Prism = window.Prism;

export const URLs = {
	marked: "https://cdn.jsdelivr.net/npm/marked/src/marked.min.js",
	DOMPurify: "https://cdn.jsdelivr.net/npm/dompurify@2.3.3/dist/purify.es.min.js",
}

// Fix indentation
function deIndent(text) {
	let indent = text.match(/^[\r\n]*([\t ]+)/);

	if (indent) {
		indent = indent[1];

		text = text.replace(RegExp("^" + indent, "gm"), "");
	}

	return text;
}

export class MarkdownElement extends HTMLElement {
	constructor() {
		super();

		this.renderer = Object.assign({}, this.constructor.renderer);

		for (let property in this.renderer) {
			this.renderer[property] = this.renderer[property].bind(this);
		}
	}

	get rendered() {
		return this.getAttribute("rendered");
	}

	get mdContent () {
		return this._mdContent;
	}

	set mdContent (html) {
		this._mdContent = html;
		this._contentFromHTML = false;

		this.render();
	}

	connectedCallback() {
		Object.defineProperty(this, "untrusted", {
			value: this.hasAttribute("untrusted"),
			enumerable: true,
			configurable: false,
			writable: false
		});

		if (this._mdContent === undefined) {
			this._contentFromHTML = true;
			this._mdContent = deIndent(this.innerHTML);
			// https://github.com/markedjs/marked/issues/874#issuecomment-339995375
			// marked expects markdown quotes (>) to be un-escaped, otherwise they won't render correctly
			this._mdContent = this._mdContent.replace(/&gt;/g, '>');
		}

		this.render();
	}

	async render () {
		if (!this.isConnected || this._mdContent === undefined) {
			return;
		}

		if (!marked) {
			marked = import(URLs.marked).then(m => m.marked);
		}

		marked = await marked;

		marked.setOptions({
			gfm: true,
			smartypants: true,
			langPrefix: "language-",
		});

		marked.use({renderer: this.renderer});

		let html = this._parse();

		if (this.untrusted) {
			let mdContent = this._mdContent;
			html = await MarkdownElement.sanitize(html);
			if (this._mdContent !== mdContent) {
				// While we were running this async call, the content changed
				// We don’t want to overwrite with old data. Abort mission!
				return;
			}
		}

		this.innerHTML = html;

		if (!Prism && URLs.Prism && this.querySelector("code")) {
			Prism = import(URLs.Prism);

			if (URLs.PrismCSS) {
				let link = document.createElement("link");
				link.rel = "stylesheet";
				link.href = URLs.PrismCSS;
				document.head.appendChild(link);
			}
		}

		if (Prism) {
			await Prism; // in case it's still loading
			Prism.highlightAllUnder(this);
		}

		// Highlight quoted text
		this.highlightQuotedText(this);

		if (this.src) {
			this.setAttribute("rendered", this._contentFromHTML? "fallback" : "remote");
		}
		else {
			this.setAttribute("rendered", this._contentFromHTML? "content" : "property");
		}

		// Fire event
		let event = new CustomEvent("md-render", {bubbles: true, composed: true});
		this.dispatchEvent(event);
	}

	static async sanitize(html) {
		if (!DOMPurify) {
			DOMPurify = import(URLs.DOMPurify).then(m => m.default);
		}

		DOMPurify = await DOMPurify; // in case it's still loading

		return DOMPurify.sanitize(html);
	}

	// Inject style dynamically
	static injectStyles() {
		let sheet = document.getElementById("md-block-syntax");
		if (!sheet) {
			sheet = document.createElement("style");
			sheet.id = "md-block-syntax";
			sheet.textContent = `
				.quote-highlight {
					color: red;
					font-weight: bold;
					cursor: pointer;
				}
			`;
			document.head.appendChild(sheet);
		}
	}

	// Recursive method to wrap quoted text in spans
	static highlightQuotedText(element) {
		const fragment = document.createDocumentFragment();
		const stack = [element];

		while (stack.length > 0) {
			const current = stack.pop();

			// Skip elements that are part of highlighted code blocks
			if (current.classList && current.classList.contains("language-")) {
				continue;
			}

			if (current.nodeType === Node.TEXT_NODE) {
				const text = current.nodeValue;
				if (!text) continue;

				// Regex matches a quote character followed by non-quote content until closing quote
				// Avoids matching inside code blocks by skipping them above
				// Matches "..." or '...'
				const regex = /(['"])(?:(?!\1).)*\1/g;

				let lastIndex = 0;
				let match;

				while ((match = regex.exec(text)) !== null) {
					if (match.index > lastIndex) {
						fragment.appendChild(document.createTextNode(text.slice(lastIndex, match.index)));
					}

					// Extract the matched quote content
					const fullMatch = match[0];
					const openQuote = match[1];
					// Construct the span
					const span = document.createElement("span");
					span.className = "quote-highlight";
					// Store full text inside span (including quotes or content, depends on preference)
					// Here we include the quotes inside the span
					span.textContent = fullMatch; 

                    fragment.appendChild(span);

					lastIndex = regex.lastIndex;
				}

				if (lastIndex < text.length) {
					fragment.appendChild(document.createTextNode(text.slice(lastIndex)));
				}
			} else if (current.nodeType === Node.ELEMENT_NODE) {
				stack.push(current);
			}
		}

		// Replace inner content of the element if we processed it
		// To avoid mutating multiple times, we attach a flag
		element.dataset.quoteProcessed = "true"; // simple safeguard logic handled internally below
        // Instead of recreating structure entirely which causes issues with node references,
        // we iterate children and replace specific text nodes.

		// Reverting to a safer approach for Element traversal without full replacement
        // which preserves existing DOM connections for other scripts/events
        const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, null, false);
        let node;

        // Reset processing flags to iterate again cleanly if called repeatedly
        if (!element.__processedHighlights) {
           element.__processedHighlights = [];
        }

        while(node = walker.nextNode()){
           if(node.parentNode && !node.parentNode.classList.contains("quote-highlight") && 
              !node.parentElement.classList.contains("quote-highlight") &&
              node.parentElement) {
              // Check if immediate parent is already a quote span to avoid double nesting
              if (!node.parentElement.classList.contains("quote-highlight")) {
                  const newText = node.nodeValue;
                  // Simple regex for quotes
                  const re = /(['"])([^"']*(?:\\"|\\')*)\1/g;

                  if (newText && newText.includes("'") || newText.includes('"')) {
                      // Check if this node is inside a code block (handled by class name check earlier usually)
                      // But here we check direct parent chain for language-
                      let p = node.parentElement;
                      let isInsideCode = false;
                      while(p) {
                          if (p.classList && p.classList.contains("language-")) {
                              isInsideCode = true;
                              break;
                          }
                          p = p.parentElement;
                      }

                      if (!isInsideCode) {
                          // Process replacements
                          const parts = [];
                          let lastIdx = 0;
                          let match;
                          // Regex to capture start quote, content, end quote
                          const quoteRegex = /(['"])(.*?)(?<!\\)\1/g;

                          while (match = quoteRegex.exec(newText)) {
                              const quoteStart = match.index;
                              const quoteFull = match[0];
                              const quoteChar = match[1];

                              if (quoteStart > lastIdx) {
                                  parts.push(document.createTextNode(newText.substring(lastIdx, quoteStart)));
                              }

                              const span = document.createElement("span");
                              span.classList.add("quote-highlight");
                              span.textContent = quoteFull;
                              parts.push(span);

                              lastIdx = quoteRegex.lastIndex;
                          }
                          if (lastIdx < newText.length) {
                              parts.push(document.createTextNode(newText.substring(lastIdx)));
                          }

                          // Create a fragment to hold this node
                          const frag = document.createDocumentFragment();
                          parts.forEach(part => frag.appendChild(part));

                          // Replace original node with fragment
                          node.parentNode.replaceChild(frag, node);
                      }
                  }
              }
           }
        }

        // Cleanup flag
        delete element.__processedHighlights;
	}
};

export class MarkdownSpan extends MarkdownElement {
	constructor() {
		super();
	}

	_parse () {
		return marked.parseInline(this._mdContent);
	}

	static renderer = {
		codespan (code) {
			if (this._contentFromHTML) {
				// Inline HTML code needs to be escaped to not be parsed as HTML by the browser
				// This results in marked double-escaping it, so we need to unescape it
				code = code.replace(/&amp;(?=[lg]t;)/g, "&");
			}
			else {
				// Remote code may include characters that need to be escaped to be visible in HTML
				code = code.replace(/</g, "&lt;");
			}

			return <code>${code}</code>;
		}
	}
}

export class MarkdownBlock extends MarkdownElement {
	constructor() {
		super();
	}

	get src() {
		return this._src;
	}

	set src(value) {
		this.setAttribute("src", value);
	}

	get hmin() {
		return this._hmin || 1;
	}

	set hmin(value) {
		this.setAttribute("hmin", value);
	}

	get hlinks() {
		return this._hlinks ?? null;
	}

	set hlinks(value) {
		this.setAttribute("hlinks", value);
	}

	_parse () {
		return marked.parse(this._mdContent);
	}

	static renderer = Object.assign({
		heading (text, level, _raw, slugger) {
			level = Math.min(6, level + (this.hmin - 1));
			const id = slugger.slug(text);
			const hlinks = this.hlinks;

			let content;

			if (hlinks === null) {
				// No heading links
				content = text;
			}
			else {
				content = <a href="#${id}" class="anchor">;

				if (hlinks === "") {
					// Heading content is the link
					content += text + "</a>";
				}
				else {
					// Headings are prepended with a linked symbol
					content += hlinks + "</a>" + text;
				}
			}

			return 
				<h${level} id="${id}">
					${content}
				</h${level}>;
		},

		code (code, language, escaped) {
			if (this._contentFromHTML) {
				// Inline HTML code needs to be escaped to not be parsed as HTML by the browser
				// This results in marked double-escaping it, so we need to unescape it
				code = code.replace(/&amp;(?=[lg]t;)/g, "&");
			}
			else {
				// Remote code may include characters that need to be escaped to be visible in HTML
				code = code.replace(/</g, "&lt;");
			}

			return <pre class="language-${language}"><code>${code}</code></pre>;
		}
	}, MarkdownSpan.renderer);

	static get observedAttributes() {
		return ["src", "hmin", "hlinks"];
	}

	attributeChangedCallback(name, oldValue, newValue) {
		if (oldValue === newValue) {
			return;
		}

		switch (name) {
			case "src":
				let url;
				try {
					url = new URL(newValue, location);
				}
				catch (e) {
					return;
				}

				let prevSrc = this.src;
				this._src = url;

				if (this.src !== prevSrc) {
					fetch(this.src)
					.then(response => {
						if (!response.ok) {
							throw new Error(Failed to fetch ${this.src}: ${response.status} ${response.statusText});
						}

						return response.text();
					})
					.then(text => {
						this.mdContent = text;
					})
					.catch(e => {});
				}

				break;
			case "hmin":
				if (newValue > 0) {
					this._hmin = +newValue;

					this.render();
				}
				break;
			case "hlinks":
				this._hlinks = newValue;
				this.render();
		}
	}
}


customElements.define("md-block", MarkdownBlock);
customElements.define("md-span", MarkdownSpan);
```

Here's a complete example of how to implement an infinite scrolling table in Vue 3 using Pinia, JavaScript, and REST APIs. It includes:

1. **Pinia Store** to handle data loading, pagination, and error states
2. **Infinite Scroll Component** to load more rows dynamically as the user scrolls
3. **Table Component** with a fixed header
4. **Styling** for proper layout behavior

---

### 1. Install Dependencies

```bash
npm install pinia vue axios @vueuse/core
```

---

### 2. Create the Pinia Store (`stores/userData.js`)

```javascript
// stores/userData.js
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import axios from 'axios'

export const useUserDataStore = defineStore('userData', () => {
  const users = ref([])
  const isLoading = ref(false)
  const hasMore = ref(true)
  const startId = ref(0)
  const totalCount = ref(0)

  // Fetch initial or additional pages
  async function fetchUsers(start = 0, count = 10) {
    isLoading.value = true
    try {
      const response = await axios.get('/api/users', {
        params: { start, count }
      })
      users.value.push(...response.data)
      if (count === 10 && response.data.length < 10) {
        hasMore.value = false
      } else {
        hasMore.value = response.data.length === count
      }
      totalCount.value += response.data.length
      startId.value += response.data.length
    } catch (error) {
      console.error('Error fetching users:', error)
    } finally {
      isLoading.value = false
    }
  }

  return {
    users,
    isLoading,
    hasMore,
    fetchUsers
  }
})
```

