<script setup>
import { ref, onMounted, onUnmounted, nextTick } from 'vue'
import { useUserDataStore } from '@/stores/userData'
import Table from './Table.vue'

const store = useUserDataStore()
const isFetching = ref(false)
const observerOptions = { rootMargin: '100px' }

const initObserver = () => {
  const loader = document.querySelector('[data-loader]')
  new IntersectionObserver(checkLoaderThreshold, {
    root: document.body,
    threshold: 0,
    rootMargin: '-100px',
    ...observerOptions
  }).observe(loader)
}

const checkLoaderThreshold = ([entry]) => {
  if (!entry.isIntersecting) return
  if (isFetching.value) return
  isFetching.value = true

  if (store.hasMore.value) {
    fetchNextPage()
  }
}

const fetchNextPage = () => {
  store.fetchUsers(store.startId.value, 10)
}

onMounted(() => {
  store.fetchUsers(0, 10)
  setTimeout(initObserver, 500)
})

onUnmounted(() => {
  const loader = document.querySelector('[data-loader]')
  const observer = new MutationObserver(removeObserverFromDom)
  removeObserverFromDom(loader)
})
</script>

