### 2. Implementation Details (Conceptual)

Since headers cannot contain long implementations, below is the necessary logic you would place in `GraphHeader.cpp`. Key parts involve mapping math coordinates to screen pixels.

```cpp
/*
 * GraphHeader.cpp Implementation Sketch
 */

using namespace ChartLib;

ChartWidget::ChartWidget() : Fl_Box(0, 0, 300, 200) {
    init();
}

void ChartWidget::init() {
    seriesList_.clear();
    config_ = {};
    config_.minX = -1000.0f; config_.maxX = 1000.0f;
    config_.minY = -1000.0f; config_.maxY = 1000.0f;
    // Ensure size is respected
    resize(300, 200); 
}

float ChartWidget::data_to_x(float dataVal) {
    if (config_.maxX <= config_.minX) return 0;
    float range = config_.maxX - config_.minX;
    return (config_.minX + dataVal) / range * config_.width();
}

float ChartWidget::data_to_y(float dataVal) {
    if (config_.maxY <= config_.minY) return 0;
    float range = config_.maxY - config_.minY;
    // FLTK Y=0 is Top, Math Y=0 is Bottom -> Flip Y
    float valPos = (config_.minY + dataVal) / range; 
    return config_.height() - (valPos * config_.height());
}

void ChartWidget::doPaint() {
    // 1. Draw Background
    fl_color(config_.backgroundColor);
    Fl_Fill_Center(config_.width(), config_.height()); // Assuming FL_COLOR fill works or use fl_box

    fl_color(FL_WHITE);
    fl_rect(0, 0, config_.width(), config_.height()); // Clear or Fill

    // Save previous clipping
    Fl_Rect old_clip = fl_clip();
    fl_clip(0, 0, config_.width(), config_.height());

    if (config_.enableGrid) {
        fl_color(config_.gridColor);
        // Simple loop to draw horizontal/vertical grid lines based on spacing
        int startX = 0;
        int endX = config_.width();
        int startY = 0;
        int endY = config_.height();

        // Draw Vertical Grid Lines (Based on config_.gridSizePixels)
        for (int x = 0; x < config_.width; x += config_.gridSizePixels) {
             // Convert pixel to data to see if it matches a nice tick...
             // Simplified: Just draw every Nth pixel
             // For better UX, you'd map data ticks to grid spacing here.
             // For this variant, let's stick to pixel spacing.
             fl_push_image(nullptr, nullptr, x, startY, startX, config_.height());
        }

        // Actually, simpler grid:
        fl_color(FL_GRAY);
        for (int x = 0; x <= config_.width; x += config_.gridSizePixels)
            fl_line(x, 0, x, config_.height);

        for (int y = 0; y <= config_.height; y += config_.gridSizePixels)
            fl_line(0, y, config_.width, y);
    }

    // Draw Series
    for (const auto& ser : seriesList_) {
        fl_color(ser.lineColor);
        fl_begin();
        for (size_t i = 0; i < ser.points.size(); ++i) {
            float px = data_to_x(ser.points[i].x);
            float py = data_to_y(ser.points[i].y);
            fl_point(px, py);
            fl_close();
        }
    }

    // Restore Clip and Draw Text (Labels)
    fl_pop_clip();

    // Left Side Y Label
    fl_color(FL_YELLOW);
    fl_font(FL_TINY);
    // Draw Title, Axis Names, etc...
}
```

