#### C. The Logic Script
This script runs when the page loads and manages the GUIDED behavior.

```javascript
<script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
<script>
    $(document).ready(function() {
        let currentStepIndex = 0;
        const totalSteps = REGISTRATION_STEPS.length;

        // Initialize first step
        updateStepView(0);

        // Global function called by buttons
        window.changeStep = function(direction) {
            const newIndex = currentStepIndex + direction;

            // Boundary checks
            if (newIndex < 0 || newIndex >= totalSteps) return;

            // Move to new step
            updateStepView(newIndex);

            // Update Button States
            document.getElementById('btnPrevious').disabled = (direction === 1); // Disable prev on start

            if (newIndex === totalSteps - 1) {
                 document.getElementById('btnNext').innerText = 'Complete';
                 document.getElementById('btnNext').onclick = submitForm;
            } else {
                 document.getElementById('btnNext').innerText = 'Next';
                 document.getElementById('btnNext').onclick = changeStep.bind(this, 1);
            }

            // Visual Guide: Update Progress Bar
            const progressPercent = ((currentStepIndex + 1) / totalSteps) * 100;
            $('#progressBar').css('width', progressPercent + '%');
        };

        function updateStepView(index) {
            currentStepIndex = index;

            // Hide all containers
            $('.step-container').removeClass('active fade-out').addClass('fade-out');

            // Show target container
            const stepId = REGISTRATION_STEPS[index].stepId;
            $('#' + stepId).addClass('active fade-out').removeClass('fade-out');

            manageAccessibility();
        }

        function manageAccessibility() {
            const currentFields = REGISTRATION_STEPS[currentStepIndex].fields;
            const workspace = $('form').find(':input');

            // Iterate through all inputs in the form (excluding hidden tracking inputs)
            $('form :input').each(function () {
                const $this = $(this);

                // Check if this input belongs to current step
                if (currentFields.includes($this.prop('name')) || 
                   ($this.attr('id') === 'checkTerms' && currentFields.includes('termsAccepted'))) {

                    // ENABLE: Remove disabled attr, add editable class
                    $this.prop('disabled', false);
                    $this.addClass('editable');

                    // Highlight specific group
                    if($this.attr('type') === 'checkbox'){
                        $this.closest('.form-check').prop('checked', false); // Reset checked to allow toggling
                        $this.val(false);
                    }
                } else {
                    // DISABLE: Keep disabled
                    $this.prop('disabled', true);
                    $this.removeClass('editable');

                    // Ensure visual feedback that it is disabled (CSS handles this)
                }
            });

            // Auto scroll to top of new section for better UX
            $('body').scrollTop(0);
        }

        function submitForm() {
            // Final validation here before sending
            if(confirm("Are you ready to finalize your registration?")) {
                document.querySelector('form').submit();
            }
        }
    });
</script>
```

