// Disjoint Set Union (DSU) structure to manage connected components
struct DSU {
    vector<int> parent;
    vector<int> min_node_idx; // Index of the house with the minimum price in this component
    vector<int> min_price;    // Price of that house

    DSU(int n, const vector<int>& prices) {
        parent.resize(n + 1);
        iota(parent.begin(), parent.end(), 0);
        min_node_idx.resize(n + 1);
        min_price.resize(n + 1);
        for (int i = 1; i <= n; ++i) {
