// Function to calculate sum of two large numbers represented as strings
string addStrings(string str1, string str2) {
    string sum = "";
    int i = str1.length() - 1;
    int j = str2.length() - 1;
    int carry = 0;

    while (i >= 0 || j >= 0 || carry) {
        int digit1 = (i >= 0) ? str1[i] - '0' : 0;
