    // 读取第一行输入的长整数字符串
    cin >> a_char;
    // 读取第二行输入的一位数
    cin >> b;

    // 根据题目要求，使用 strlen 计算 char 数组的长度，用于确定 for 循环次数
    n = strlen(a_char);

    // 使用 '-'0' 的方式将 char 数组中的每一位转换为 int 类型的数值并存入数组
    // 同时配合 for 循环完成转换
    for(i = 0; i < n; i++) {
        a_num[i] = a_char[i] - '0';
    }

    // 使用变量 carry 存储当前的进位值，初始化时为 b
    int carry = b;

    // 从个位开始向高位进行加法计算
    // i 从 n-1 递减到 0
    for(i = n - 1; i >= 0; i--) {
        // 累加当前位数字与进位值
        int sum = a_num[i] + carry;

        // 处理溢出：取余得到当前位结果，整除得到新进位
        a_num[i] = sum % 10;
        carry = sum / 10;
    }

    // 输出结果的逻辑
    // 需要检查计算完成后是否还剩下最高位的进位
    if (carry > 0) {
        // 有额外进位时，先输出最高位
        cout << carry;
    }

    // 按照原有顺序输出整型数组中的数字（此时数组内存储的是计算后的高低位对齐结果）
    for(i = 0; i < n; i++) {
        cout << a_num[i];
    }
    // 输出换行
    cout << endl;

    return 0;
}
```

### 代码实现思路

这个问题是经典的“平面图形面积计算”问题，通常称为“Rectangle Area II"。由于坐标范围很大（$10^9$），不能直接建立网格，必须使用**扫描线算法（Sweep Line）**配合**离散化**和**线段树（Segment Tree）**来解决。

#### 核心步骤：
1.  **坐标离散化**：提取所有矩形的 $y$ 轴坐标（$y1, y2$），排序并去重，得到一系列 $Y$ 轴的基本区间。这些区间的长度即为线段树的叶子节点贡献。
2.  **构建事件**：将每个矩形转化为两个事件：
    *   矩形左边界 $x1$：类型为进入（`+1`）。
    *   矩形右边界 $x2$：类型为离开（`-1`）。
3.  **扫描线处理**：
    *   将所有事件按 $x$ 坐标排序。
    *   依次处理事件。在相邻的两个 $x$ 坐标之间（$\Delta X$），查询当前 $Y$ 轴方向上的覆盖总长度（由线段树维护的根节点覆盖长度）。
    *   累加面积 $\Delta X \times \text{CoveredHeight}$。
    *   更新线段树，反映当前 $x$ 处覆盖情况的变化。
4.  **结果计算**：由于题目保证总面积可用 64 位整数存储，且要求对 $10^9+7$ 取模，我们先用 `long long` 累加精确面积，最后取模。

### C++ 代码

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

// 常量定义
const long long MOD = 1e9 + 7;

// 事件结构体
struct Event {
    int x;
    int type; // 1 表示矩形开始，-1 表示矩形结束
    int y1, y2;
};

// 比较函数：先按 x 排序，x 相同则按 type 排序（这里顺序不影响正确性，因为面积是在 x 变化时计算的）
bool compareEvents(const Event& a, const Event& b) {
    if (a.x != b.x) return a.x < b.x;
    return a.type > b.type; // 为了调试方便，也可不用关心 type 的顺序
}

// 全局变量用于线段树
vector<int> Ys;         // 离散化后的 Y 坐标
vector<long long> cnt;  // 每个节点的覆盖次数
vector<long long> len;  // 每个节点实际覆盖的长度
int n_rect_intervals;   // 基本区间数量 (Ys.size() - 1)

// 线段树下推/更新逻辑
void pushUp(int node, int l, int r) {
    if (cnt[node] > 0) {
        // 如果被标记覆盖，则该节点代表的整个 Y 区间都被覆盖
        // l 和 r 在这里代表的是 Ys 数组的下标索引区间 [l, r)
        len[node] = Ys[r] - Ys[l];
    } else {
        // 如果没有被标记，则长度等于子节点覆盖长度之和
        len[node] = len[2 * node] + len[2 * node + 1];
    }
}

// 更新函数：在 Y 轴区间 [ql, qr) 上增加 coverage val
void update(int node, int l, int r, int ql, int qr, int val) {
    if (ql <= l && r <= qr) {
        cnt[node] += val;
        pushUp(node, l, r);
    } else {
        int mid = l + (r - l) / 2;
        // 注意：这里是基于下标的递归。叶子节点对应 Ys 中的单个区间 [Ys[i], Ys[i+1])
        // 所以递归终止条件是 ql <= l && r <= qr 或者到达叶子层
        if (ql < mid) update(2 * node, l, mid, ql, min(qr, mid), val);
        if (qr > mid) update(2 * node + 1, mid, r, max(ql, mid), qr, val);

        pushUp(node, l, r);
    }
}

// 为了方便理解，重写一下 update 的逻辑以匹配常见的实现风格
// 标准写法：如果完全包含则更新 cnt，否则分裂。pushUp 在之后执行。
void updateStandard(int node, int l, int r, int ql, int qr, int val) {
    if (ql <= l && r <= qr) {
        cnt[node] += val;
    } else {
        int mid = l + (r - l) / 2;
        if (ql < mid) updateStandard(2 * node, l, mid, ql, qr, val);
        if (qr > mid) updateStandard(2 * node + 1, mid, r, ql, qr, val);
    }
    // 向上更新长度
    pushUp(node, l, r);
}

int main() {
    // 优化输入输出速度
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<Event> events;
    events.reserve(2 * n);
    Ys.clear();
    Ys.reserve(2 * n);

    for (int i = 0; i < n; ++i) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        events.push_back({x1, 1, y1, y2});
        events.push_back({x2, -1, y1, y2});
        Ys.push_back(y1);
        Ys.push_back(y2);
    }

    // 坐标离散化 (Y 轴)
    sort(Ys.begin(), Ys.end());
    Ys.erase(unique(Ys.begin(), Ys.end()), Ys.end());

    // 生成线段树的大小 (元素个数为 Ys.size() - 1)
    n_rect_intervals = Ys.size() - 1;
    int sz = 4 * n_rect_intervals;
    cnt.assign(sz, 0);
    len.assign(sz, 0);

    // 排序事件
    sort(events.begin(), events.end(), compareEvents);

    long long totalArea = 0;
    int lastX = 0;

    // 遍历事件
    for (const auto& e : events) {
        if (e.x > lastX) {
            // 计算从 lastX 到当前事件 x 之间的面积
            // 当前覆盖的高度是线段树根节点的有效长度
            long long h = len[1];
            if (h > 0) {
                totalArea += (long long)(e.x - lastX) * h;
            }
            lastX = e.x;
        }

        // 更新线段树
        // 映射 Y 坐标到离散化后的索引
        // y1 对应的下标
        int l = lower_bound(Ys.begin(), Ys.end(), e.y1) - Ys.begin();
        // y2 对应的下标 - 1 (因为是区间 [l, r)，r 是 e.y2 的索引)
        int r = lower_bound(Ys.begin(), Ys.end(), e.y2) - Ys.begin() - 1;

        // 只有当存在有效区间时才更新
        if (l <= r) {
            updateStandard(1, 0, n_rect_intervals, l, r + 1, e.type);
        }
    }

    cout << totalArea % MOD << endl;

    return 0;
}
```

### 代码解析
1.  **输入处理**：读取矩形数量 $N$，然后循环读取坐标。同时记录 $y$ 轴坐标用于离散化。
2.  **坐标压缩**：对所有 $y$ 坐标排序并去重，存储在 `Ys` 向量中。这将连续的 $Y$ 轴转换为离散的段，每段长度为 `Ys[i+1] - Ys[i]`。
3.  **线段树构建**：
    *   `cnt` 数组记录每个节点被多少矩形完全覆盖。
    *   `len` 数组记录当前节点范围内被覆盖的实际长度总和。
    *   `updateStandard` 函数负责区间加操作。如果一个节点被 `cnt > 0` 完全覆盖，其 `len` 就是该节点的完整几何长度；否则为左右子节点 `len` 之和。
4.  **扫描线逻辑**：
    *   将事件按 $x$ 排序。
    *   每次处理一个新 $x$ 坐标前，计算 `lastX` 到当前 $x$ 的距离乘以当前覆盖高度 `len[1]`，累加到总面积。
    *   更新线段树，将当前矩形的 $y$ 区间映射到离散化后的索引上进行加减操作（进/出）。
5.  **输出**：最终结果对 $10^9 + 7$ 取模。题目保证了总面积不溢出 64 位整数，因此先精确求和再取模即可。

### 复杂度分析
*   **时间复杂度**：$O(N \log N)$。主要是事件排序 $O(N \log N)$ 和线段树更新 $O(N \log N)$（因为有 $2N$ 个事件，离散化后 Y 坐标数不超过 $2N$）。对于 $N=50$，效率极高。
*   **空间复杂度**：$O(N)$。用于存储事件、离散化坐标和线段树。

此解法符合题目给出的“线段树”章节要求，并能正确处理大坐标和重叠区域。

