            System.out.printf("（实际路径总数 %d 条，此处仅展示前 50 条）\n", solver.getPathCount());
        }

        // 显示部分示例路径的结构
        System.out.println("\n--- 示例路径结构 ---");
        for (int i = 0; i < Math.min(10, solver.getPathCount()); i++) {
            String path = allPaths.get(i);
            System.out.printf("%2d.%s -> 共%d步\n", i + 1, path, countSteps(path));
        }
    }

    // 递归生成所有路径并计数
    private static void solve(Staircase st, int currentLevel, int totalLevels) {
        if (currentLevel == totalLevels) {
            st.allPaths.add("→".repeat(st.getStepSequence().size()));
            st.pathCount++;
            return;
        }
        if (currentLevel > totalLevels) {
            return;
        }
        // 走一步
        solve(st, currentLevel + 1, totalLevels);
        // 走两步
        if (currentLevel + 2 <= totalLevels) {
            solve(st, currentLevel + 2, totalLevels);
        }
    }
}
