### C++ 实现代码

以下代码实现了基于向量代数的高效判断逻辑，并包含了必要的几何工具类和容差设置。

```cpp
#include <iostream>
#include <cmath>
#include <algorithm>
#include <vector>
#include <limits>

// 使用高精度浮点数
typedef double FloatType;

const FloatType EPSILON = 1e-8f; // 用于浮点数比较的容差

// ----------------- 基础结构定义 -----------------
struct Point2D {
    FloatType x, y;
    Point2D(FloatType _x = 0, FloatType _y = 0) : x(_x), y(_y) {}
};

// 简单的二维向量运算类
struct Vec2 {
    FloatType x, y;
    static Vec2 operator-(const Vec2& a, const Vec2& b) { return {a.x - b.x, a.y - b.y}; }
    static Vec2 operator+(const Vec2& a, const Vec2& b) { return {a.x + b.x, a.y + b.y}; }
    static Vec2 operator*(FloatType s) { return {s * x, s * y}; }
    FloatType Dot(const Vec2& b) const { return x * b.x + y * b.y; }
    FloatType LenSq() const { return x * x + y * y; }
    FloatType Len() const { return std::sqrt(LenSq()); }

    // 归一化
    Vec2 Normalize() const { 
        FloatType l = Len(); 
        return (l > 0) ? (*this) / l : Vec2(0, 0); 
    }

    // 与法向量的叉积模长 (用于判断平行度)
    // n 是 Cover 的法向量 (dx, dy) -> (-dy, dx)
    // 这里简化直接返回 |u x v| 的近似值：|u_x * v_y - u_y * v_x|
    FloatType CrossMag(const Vec2& b) const { 
        return std::abs(x * b.y - y * b.x); 
    }
};

struct CustomLine {
    Point2D start;
    Point2D end;
    FloatType width;
};

// ----------------- 辅助数学函数 -----------------
FloatType distPointToSegmentSquared(Point2D p, Point2D a, Point2D b) {
    // 计算点到最近点的平方距离
    Vec2 ab = b - a;
    Vec2 ap = p - a;
    FloatType l2 = ab.LenSq();
    if (l2 == 0) return ap.LenSq(); // 起点重合

    FloatType t = ap.Dot(ab) / l2;
    t = std::clamp(t, 0.0f, 1.0f);
    Vec2 projected = a + ab * t;
    Vec2 diff = p - projected;
    return diff.LenSq();
}

// 获取点在直线上的参数 t (无限长直线上)
FloatType getParameterT(Point2D point, Point2D lineStart, Point2D lineEnd) {
    Vec2 dir = lineEnd - lineStart;
    FloatType l2 = dir.LenSq();
    if (l2 == 0) return 0.0; 
    Vec2 dp = point - lineStart;
    return dp.Dot(dir) / l2;
}

// ----------------- 核心判断逻辑 -----------------
/**
 * 判断 CustomLine target 是否完全被 CustomLine cover 覆盖
 * @return true 表示完全覆盖，false 否则
 */
bool isFullyCovered(const CustomLine& target, const CustomLine& cover) {
    // 1. 宽度必要条件：覆盖者线宽不能小于目标线宽
    if (cover.width < target.width - EPSILON) {
        return false;
    }

    // 2. 计算方向向量并归一化
    Vec2 v_tgt = target.end - target.start;
    Vec2 v_cov = cover.end - cover.start;

    FloatType len_tgt = v_tgt.Len();
    FloatType len_cov = v_cov.Len();

    if (len_tgt == 0 || len_cov == 0) {
        // 零长度线段视为点覆盖，需检查点是否在对方的带内
        // 简单处理：如果都是点，则需重合；如果一个为零，看点在对方线段附近
        // 这里为了通用性，先假设不为零，或退化情况单独考虑
        // 实际业务中通常忽略零宽退化
        return false; 
    }

    Vec2 dir_tgt = v_tgt.Normalize();
    Vec2 dir_cov = v_cov.Normalize();

    // 2b. 平行性检查
    // 两个向量的角度误差必须在极小范围内
    FloatType cosTheta = std::abs(dir_tgt.Dot(dir_cov));
    // 允许的最大角度余弦值 (接近 1.0)，例如 1.0 表示完全同向，0.99 表示非常接近
    // 使用 CrossProduct Magnitude 更直观：|u x v| <= sin(theta)
    FloatType crossProd = v_tgt.CrossMag(v_cov.Normalize());
    // 或者直接用方向向量的叉积绝对值作为不平行度的指标
    // 若两线不平行，目标线的端点迟早会跑出容器的边缘（即使中心线距离满足）
    // 只有当夹角非常小的时候，我们可以认为它们共线
    if (std::abs(cosTheta) < (1.0 - 1e-5)) {
         // 如果方向差异明显（如垂直），直接返回 false
         // 但考虑到可能有微小旋转，我们结合宽度容差判断
         // 理论上严格覆盖要求 theta=0。此处放宽至 0.01 rad (~0.5度) 视精度需求而定
         return false; 
    }

    // 确保方向大致一致 (避免反向导致投影混乱，虽然投影取区间可以兼容反向)
    // 如果反向但共线，几何上是成立的。只需保证中心线重合即可。

    // 3. 检查中心线之间的最大距离
    // 公式：max_dist_between_lines <= (width_cover - width_target) / 2
    // 对于平行线段，最大距离出现在端点处。我们需要检查 Target 的端点到 Cover 直线的距离

    FloatType safeMargin = (cover.width - target.width) / 2.0;
    if (safeMargin < EPSILON) {
        // 宽度相等时，中心线必须重合
        if (getPerpDistance(target.end, cover.start, cover.end) > EPSILON ||
            getPerpDistance(target.start, cover.start, cover.end) > EPSILON) {
             return false;
        }
    } else {
        // 有宽度容差，检查距离是否超标
        // 计算目标起点和终点到覆盖直线所在直线的垂直距离
        FloatType d_start = getPerpDistance(target.start, cover.start, cover.end);
        FloatType d_end = getPerpDistance(target.end, cover.start, cover.end);

        if (std::max(d_start, d_end) > safeMargin + EPSILON) {
            return false;
        }
    }

    // 4. 纵向投影检查
    // Target 的投影区间 [t_min, t_max] 必须完全在 Cover 的区间 [c_min, c_max] 内
    // 注意：需要统一坐标系。这里将 Target 端点投影到 Cover 线段所在的直线上

    FloatType t_start_proj = getParameterT(target.start, cover.start, cover.end);
    FloatType t_end_proj = getParameterT(target.end, cover.start, cover.end);

    FloatType cover_len = len_cov;

    // 处理反向情况，投影参数可能是负数（取决于起终点顺序）
    // 我们取 Cover 的整个有效区间为 [-cover_len, +cover_len] 相对起点？
    // 不对，是 [0, len_cov]。但因为 target 可能比 cover 短，所以只要投影落在 [0, len_cov] 内即可
    // 修正：为了严谨，我们应该把 Cover 线段视为参数空间 [0, len_cov]。
    // 如果 Target 的反向，投影值应该也映射进去。

    // 标准化投影范围
    FloatType min_t = std::min(t_start_proj, t_end_proj);
    FloatType max_t = std::max(t_start_proj, t_end_proj);

    FloatType cover_min = 0.0;
    FloatType cover_max = cover_len;

    // 如果 Cover 也是反向定义，这里的区间依然是物理意义上的起点到终点的范围
    // 关键是：Target 的实体部分投影后，是否全部落在了 Cover 定义的物理线段范围内？
    // 由于上面已经检查了平行度，我们假设它们在几何上是对齐的轴线。
    // 现在只需要确认 Target 没有伸展出 Cover 的末端。

    if (min_t < -EPSILON || max_t > cover_max + EPSILON) {
        // 注意：因为 Cover 也有宽度，如果 Target 只是稍微伸出一点点，但仍在 Cover 的宽度扩展区域内呢？
        // 实际上 "完全覆盖" 意味着所有像素都在 Cover 颜色块内。
        // 因此，Target 的中心线投影点绝不能超出 Cover 线段的端点（忽略微小的宽度容差导致的视觉误差，除非我们定义覆盖包含角部）
        // 严格来说：Target 的 Capsule 形状不能完全超出 Cover 的 Capsule 形状。
        // 这意味着 Target 的端点投影不应超过 Cover 的端点过多（受限于自身宽度）。
        // 但在标准线段模型下，通常要求投影区间完全包含。
        // 考虑到 Target 自身也有宽度，它的有效覆盖范围可能稍微向外延伸。
        // 保守策略：中心线投影完全在 Cover 内部。

        // 优化：允许 Target 的尖端在 Cover 线宽边界内略有超出？
        // 不，题目要求完全覆盖。如果 Target 的角落超出了 Cover 的边缘，就算未覆盖。
        // 所以最严苛的条件是：Target 中心线的投影必须在 Cover 线段内部。
        // 为什么？因为如果中心线投影出来了，那么 Target 的最外侧肯定也出来了（除非 Cover 更宽？不，我们已有宽度检查）。

        return false;
    }

    // 特殊情况：如果 Cover 线段很短，Target 线段很长，但 Target 的一部分在 Cover 外部，
    // 上面的 min_t < 0 或 max_t > cover_max 已经捕获。

    return true;
}

// 辅助函数：计算点到直线的垂直距离 (无符号)
FloatType getPerpDistance(Point2D p, Point2D a, Point2D b) {
    Vec2 ab = b - a;
    Vec2 ap = p - a;
    FloatType len_sq = ab.LenSq();
    if (len_sq < 1e-16) return std::abs(ap.x) + std::abs(ap.y); // 线段为点的情况
    return std::abs(ap.CrossMag(ab.Normalize())); 
    // 等价于叉积除以长度：|ap x ab| / |ab|
}

int main() {
    // 示例数据
    // Cover: 从 (0,0) 到 (100, 0)，宽 20
    // Target: 从 (20,0) 到 (80, 0)，宽 10 (应该被覆盖)
    // Case 1: Covered
    CustomLine cov1 = {{0.0, 0.0}, {100.0, 0.0}, 20.0};
    CustomLine tgt1 = {{20.0, 0.0}, {80.0, 0.0}, 10.0};

    // 修改数据：Target 宽度更大
    // Case 2: Width Mismatch
    CustomLine tgt2 = {{20.0, 0.0}, {80.0, 0.0}, 30.0}; 

    // 修改数据：Target 位置偏移
    // Case 3: Offset (Centerline mismatch)
    CustomLine tgt3 = {{20.0, 5.0}, {80.0, 5.0}, 10.0}; // 偏离了 5px，Cover 宽 20 -> HalfDiff 5px -> 刚好临界

    std::cout << "Case 1 (Perfect): " << isFullyCovered(tgt1, cov1) << std::endl;
    std::cout << "Case 2 (Too Wide): " << isFullyCovered(tgt2, cov1) << std::endl;
    std::cout << "Case 3 (Offset Edge): " << isFullyCovered(tgt3, cov1) << std::endl; // 此时 dist=5, margin=5 -> True

    return 0;
}
```

### 数学原理详解

为了确保你理解代码背后的逻辑，以下是关键的数学判断依据：

#### 1. 宽度约束 ($w_{cover} \ge w_{target}$)
这是最直观的必要条件。如果容器比内容细，无论怎么摆放，内容的边缘必然会超出容器的边界。
数学表达：$2r_{cover} \ge 2r_{target}$。

#### 2. 平行性约束 (Collinearity)
两条有限的线段要构成包含关系，它们的中心轴线必须是共线的（或者说夹角趋近于 0）。
*   **原因**：如果有夹角 $\theta \neq 0$，随着线段长度增加，两条线中心的垂直距离 $d = L \cdot \sin(\theta)$ 会线性增加。
*   **判定**：计算两向量归一化后的点积（Cosine Similarity）。如果接近 1 或 -1，则认为平行。如果不平行，即使中心线距离很近，两端也会发生交叉超出。
*   **例外**：如果夹角非常小，且容器的宽度足够大以吞没因夹角产生的位移，理论上可能成立，但这需要极其复杂的布尔运算。本实现采用工程级做法：**强制要求高度平行**，这在实际图形学中通常就是“覆盖”的定义。

#### 3. 横向距离约束 (Lateral Distance)
即使平行，目标线段也不能跑偏。
*   **公式**：$\max(dist(TargetStart, CoverLine), dist(TargetEnd, CoverLine)) \le \frac{w_{cover} - w_{target}}{2}$
*   **解释**：$w_{cover}$ 提供了总带宽，减去 $w_{target}$ 后，剩余的部分需要在左右两边各留出 $\frac{\Delta w}{2}$ 的空间来放置目标线段的偏移。
*   该计算利用了点到直线的距离公式：$d = \frac{|ax+by+c|}{\sqrt{a^2+b^2}}$，代码中使用了向量叉积形式来计算。

#### 4. 纵向投影约束 (Projection Interval)
即使中心线重合且宽度足够，目标线段也不能比覆盖线段长，否则会两头伸出。
*   **方法**：将目标线段的起点和终点坐标投影到覆盖线段所在的轴线上，得到参数 $t \in [0, L_{cover}]$。
*   **判定**：$t_{start}, t_{end}$ 必须满足 $0 \le t \le L_{cover}$（允许微小误差 EPSILON）。
*   这意味着目标线段完全处于覆盖线段的物理长度范围内。

### 注意事项
1.  **浮点精度**：代码中引入了 `EPSILON`。在计算机图形学中使用 `float` 或 `double` 进行比较时，永远不要使用 `==`，而应使用 `fabs(a-b) < EPSILON`。
2.  **性能**：此算法为 O(1)，非常适合在游戏引擎、CAD 库或渲染器中进行实时碰撞检测和层级判定。
3.  **特殊形状**：上述代码假设线段是标准的“胶囊形”（圆角矩形端点）。如果你的线段端点是方形（直角），则投影判断时的端点容许范围可能需要微调，但核心逻辑不变。

这个实现方案平衡了数学严谨性和 C++ 实现的简洁性。

Dưới đây là mã nguồn thực hiện thuật toán Euclid mở rộng (Extended Euclidean Algorithm) trong ngôn ngữ lập trình C, được viết bám sát vào các bước bạn đã cung cấp (đã chỉnh sửa lỗi chính tả và ký hiệu để dễ hiểu hơn).

### Mã nguồn (Source Code)

```c
#include <stdio.h>

// Hàm trả về ước chung lớn nhất (d) và hệ số x, y sao cho: a*x + b*y = d
void extendedEuclid(long long a, long long b, long long *d, long long *x, long long *y) {
    // Biến tương ứng với các biến trong mô tả của bạn: X2, X1, Y2, Y1
    long long x2 = 1;
    long long x1 = 0;
    long long y2 = 0;
    long long y1 = 1;

    // Bước (1): Nếu b = 0 thì kết thúc ngay
    // Trong vòng lặp While ở bước (3), điều kiện b > 0 sẽ xử lý điều này tự động
    // Tuy nhiên, nếu b ban đầu bằng 0, hàm vẫn hoạt động đúng theo logic sau

    // Bước (3): While b > 0 do
    while (b > 0) {
        // 3.1. Tính thương q, dư r
        // Và cập nhật tạm thời hệ số X mới (kí hiệu tạm là nx, ny)
        long long q = a / b;
        long long r = a % b; // Tương đương: a - q*b

        long long nx = x2 - q * x1;
        long long ny = y2 - q * y1;

        // 3.2. Cập nhật lại giá trị a, b (đổi chỗ giống như phép chia lấy dư cơ bản)
        a = b; 
        b = r; 

        // Cập nhật lại hệ số theo thứ tự luân chuyển:
        // X2 trở thành X1 cũ
        // X1 trở thành giá trị X tính vừa xong
        x2 = x1;
        x1 = nx;

        y2 = y1;
        y1 = ny;

        // (Lưu ý: Trong đề bài ghi "X2 + X1" nhưng theo thuật toán chuẩn và logic bước 3.1
        // thì đây là thao tác thay thế/gán giá trị cũ lên vị trí cũ)
    }

    // Bước (4): Đặt kết quả cuối cùng
    // Tại thời điểm này b = 0, nên a chứa đúng ƯCLN (GCD)
    // Hệ số nằm tại x2 và y2
    *d = a;
    *x = x2;
    *y = y2;

    printf("Kết quả:\n");
    printf("Độ dài ước chung lớn nhất (d): %lld\n", *d);
    printf("Hệ số x: %lld\n", *x);
    printf("Hệ số y: %lld\n", *y);
    printf("Kiểm tra lại: (%lld)*(%lld) + (%lld)*(%lld) = %lld\n", 
           *a_input_var, *x, *b_input_var, *y, (*a_input_var * *x + *b_input_var * *y));
}

int main() {
    long long a_in = 30;
    long long b_in = 12;
    long long d, x, y;

    printf("Chạy với a = %lld, b = %lld\n\n", a_in, b_in);
    extendedEuclid(a_in, b_in, &d, &x, &y);

    return 0;
}
```

### Giải thích chi tiết sự tương ứng giữa mã nguồn và bài toán:

Bạn có thể thấy phần bình luận trong hàm `extendedEuclid` giải thích từng bước:

1.  **Biến khởi tạo (Bước 2):**
    *   Đề bài: $X_2 = 1, X_1 = 0, Y_2 = 0, Y_1 = 1$
    *   Code: Khởi tạo `long long x2 = 1; x1 = 0; y2 = 0; y1 = 1;`
    *   *(Lý do: Chúng ta cần lưu trữ hệ số của các lần trừ trước đó để cập nhật liên tiếp)*

2.  **Vòng lặp (Bước 3):**
    *   Kiểm tra điều kiện `while (b > 0)`.
    *   **3.1:**
        *   Tính `q = a / b`.
        *   Tính `r = a % b` (hoặc `r = a - q * b`).
        *   Tính toán hệ số mới: `nx = x2 - q * x1`, `ny = y2 - q * y1`.
        *   *(Đây là công thức cơ bản của thuật toán mở rộng để duy trì tính đồng cấu)*.
    *   **3.2:**
        *   Dịch chuyển dữ liệu: `a = b` và `b = r`.
        *   Dịch chuyển hệ số: `x2 <- x1`, `x1 <- nx`. Tương tự cho `y`.
        *   *(Điều này đảm bảo trong vòng lặp tới, biến `x2, y2` luôn giữ nghiệm hợp lệ cho bộ `a, b` mới)*.

3.  **Trả về kết quả (Bước 4):**
    *   Khi vòng lặp kết thúc thì `b` sẽ bằng 0.
    *   Lúc đó `a` là ước chung lớn nhất (`d`).
    *   Các hệ số đối ứng được lưu ở biến `x2` và `y2`.
    *   Code gán `*d = a; *x = x2; *y = y2;`.

