% 清空工作区和关闭所有图形窗口
clear; close all; clc;

% 定义全局变量 (确保在工作区顶部声明，以便函数识别)
global DH_params target_pos joint_inertia joint_avg_speed;

% --- 参数设置 ---
% 设置 DH 参数 [a, alpha, d, theta_min, theta_max]
% 注意：alpha 为弧度制的标准是 rad，但输入通常方便写度数，后面转换即可
DH_params = [
    300, -90, 600, -160, 160;
    1200, 0,   0, -150,  15;
    300, -90,  0, -200,  80;
    0,   -90, 1200, -180, 180;
    0,   -90,  0, -120, 120;
    0,    0,   0, -180, 180
];

target_pos = [1500; 1200; 200];  % 目标位置 (mm)
joint_inertia = [0.5, 0.3, 0.4, 0.6, 0.2, 0.4];  % 关节转动惯量
joint_avg_speed = [2.0, 1.5, 1.0, 2.5, 3.0, 2.0];  % 关节平均角速度 (假设单位为 rad/s 作为权重)

% 设置多目标遗传算法选项
opts = optimoptions('gamultiobj', 'PopulationSize', 500, 'MaxGenerations', 50, ... % 适当减小以测试运行
    'PlotFcn', {@gaplotpareto}, 'Display', 'iter');

% 多启动法参数
numStarts = 3; % 建议初始次数设为 3，过多会耗时
bestSolutions = cell(numStarts, 1);
bestFvals = cell(numStarts, 1);

fprintf('开始执行多起点优化...\n');

for start = 1:numStarts
    fprintf('第 %d 次运行...\n', start);

    % 运行多目标优化
    % 注意：gamultiobj 参数顺序：fun, nvars, A, b, Aeq, beq, lb, ub, nonlcon, opts
    % 这里前 5 个空矩阵代表线性约束，第 6 个 (lb) 和 第 7 个 (ub) 为边界，第 8 个为非线性约束
    [x, fval] = gamultiobj(@objective_function, 6, [], [], [], [], ...
        deg2rad(DH_params(:,4)), deg2rad(DH_params(:,5)), @constraint_function, opts);

    % 存储结果
    bestSolutions{start} = x;
    bestFvals{start} = fval;

    % 可视化当前运行的 Pareto 前沿
    visualize_results(start, fval);
    disp_results(x, fval, start);
end

% --- 全局最优解筛选 ---
globalBestFval = [inf, inf];
globalBestSolution = [];
countOfRuns = numStarts;

% 遍历所有启动的结果，寻找支配关系或最优点
for i = 1:countOfRuns
    [localMinErr, localMinIdx] = min(bestFvals{i}(:,1));

    % 避免浮点数直接比较使用容差，或者直接比较向量大小
    isNewGlobalBest = false;

    % 检查当前找到的局部最优是否比历史记录更优 (误差更小，或误差相同则能耗更低)
    if (isnan(localMinErr)) continue; % 防御性编程

    if (localMinErr < globalBestFval(1))
        isNewGlobalBest = true;
    elseif (abs(localMinErr - globalBestFval(1)) < 1e-6 && ...
          bestFvals{i}(localMinIdx,2) < globalBestFval(2))
        isNewGlobalBest = true;
    end

    if isNewGlobalBest
        globalBestFval = bestFvals{i}(localMinIdx, :);
        globalBestSolution = bestSolutions{i}(localMinIdx, :);
    end
end

% 显示全局最优解
disp('------------------------------------------');
disp('全局最优解发现完成。');
disp('==========================================');
disp('最佳 - 关节角度 (度):');
disp(array2table(rad2deg(globalBestSolution), 'VariableNames', {'Joint1', 'Joint2', 'Joint3', 'Joint4', 'Joint5', 'Joint6'}));
disp('最佳 - 目标函数值 (Error_mm, Energy_J):');
disp(array2table(globalBestFval, 'VariableNames', {'EndEffectorError_mm', 'EnergyConsumption_J'}));


%% --- 目标函数及辅助子函数 ---

% 目标函数：最小化末端误差和能耗
function f = objective_function(theta)
    global target_pos joint_inertia joint_avg_speed;

    % 1. 正向运动学 (计算一次)
    [end_pos, ~] = forward_kinematics(theta);

    % 误差项
    f(1) = norm(end_pos - target_pos);

    % 能耗项 (动能估算 + 重力势能估算)
    % 修正：重力势能只计算 z 轴高度 (end_pos(3))，而不是 x+y+z 的和
    mass = 5; 
    g = 9.81; 

    % 势能修正：U = m * g * h
    gravitational_energy = mass * g * end_pos(3); 

    % 机械损耗/动能近似：基于位置和惯性的启发式指标
    % 原代码：joint_inertia .* (joint_avg_speed .* theta).^2
    % 修正：去掉不合理的物理维度混用，此处保留原意图但移除对 FK 的重复依赖
    speed_cost = sum(joint_inertia .* joint_avg_speed ./ abs(joint_avg_speed+eps) .* theta); 
    % 为了兼容原公式逻辑，如果坚持原公式需保持单位一致，这里简单处理为加权
    mechanical_cost = sum(joint_inertia .* abs(theta) .* joint_avg_speed .* 0.5); 

    % 综合能耗
    f(2) = mechanical_cost + gravitational_energy; 
end

% 约束函数：限制末端误差不超过 200mm
function [c, ceq] = constraint_function(theta)
    global target_pos;
    [end_pos, ~] = forward_kinematics(theta);

    % 非线性不等式约束 c(x) <= 0
    c = norm(end_pos - target_pos) - 200;
    ceq = [];
end

% 正向运动学计算
function [end_pos, T] = forward_kinematics(theta)
    global DH_params;
    T = eye(4);
    for i = 1:6
        T = T * dh_matrix(DH_params(i,:), theta(i));
    end
    end_pos = T(1:3,4);
end

% DH 矩阵计算 (Standard DH Convention)
function T = dh_matrix(params, theta)
    a = params(1); alpha = deg2rad(params(2)); d = params(3);
    T = [
        cos(theta),  -sin(theta)*cos(alpha),  sin(theta)*sin(alpha), a*cos(theta);
        sin(theta),   cos(theta)*cos(alpha), -cos(theta)*sin(alpha), a*sin(theta);
        0,            sin(alpha),              cos(alpha),            d;
        0,            0,                        0,                     1
    ];
end

