%% 函数定义：基于向量内积法的稳态点投影计算
function target_point = project_steady_state(Q, P_matrix)
    % Q: 1x2 向量，待估计点
    % P_matrix: Nx2 矩阵，所有稳态点

    P1 = P_matrix(1, :);         % 第一个稳态点 (起点)
    PN = P_matrix(end, :);       % 最后一个稳态点 (终点)

    % (1) 形成简化的基线向量 Base
    Base_Vector = PN - P1;

    % (2) 构建设计向量 (从 P1 到 Q)
    Vector_PQ = Q - P1;

    % 防止除零错误：如果基线向量为零向量 (即只有一个点或重合)
    norm_Base_sq = dot(Base_Vector, Base_Vector);
    if norm_Base_sq == 0
        error('错误：两个端点重合，无法形成有效的基线向量。请检查输入数据。');
    end

    % (2) 由向量知识可知：使用点积求投影系数 t
    % Formula: t = (PQ . Base) / |Base|^2
    t = dot(Vector_PQ, Base_Vector) / norm_Base_sq;

    % 计算交点坐标 (投影点)
    % P_target = P1 + t * Base
    target_point = P1 + t * Base_Vector;
end

%% 辅助绘图函数
function plot_plot_data(Q, P_mat, ProjPt)
    % 绘制所有原始点
    scatter(P_mat(:,1), P_mat(:,2), 80, 'b.', 'DisplayName', '原始稳态点集');

    % 绘制基线 (P1-PN 连线)
    hold on;
    P1 = P_mat(1,:);
    PN = P_mat(end,:);
    plot([P1(1) PN(1)], [P1(2) PN(2)], 'r-', 'LineWidth', 2, 'DisplayName', '基线 P1-PN');

    % 绘制待估计点
    plot(Q(1), Q(2), 'go', 'MarkerSize', 10, 'LineWidth', 2, 'DisplayName', '待估计点');

    % 绘制投影线段 (视觉辅助)
    plot([Q(1) ProjPt(1)], [Q(2) ProjPt(2)], 'g--', 'LineWidth', 1, 'DisplayName', '垂线辅助');
    plot([ProjPt(1) ProjPt(1)], [Min(P1(2),PN(2)):1:Max(P1(2),PN(2))+1], 'g-', 'LineWidth', 1); 
    % 简单示意，通常垂直线画到基线即可

    % 绘制交点
    plot(ProjPt(1), ProjPt(2), 'ms', 'MarkerFaceColor', 'm', 'MarkerSize', 12, 'DisplayName', '目标稳态点 (交点)');

    axis equal;
    grid on;
    box on;
end

%% 辅助函数：查找最近的实际稳态点索引 (补充功能)
function idx = find_min_nearest_index(Q, ProjPt, P_mat)
    dists = sqrt(sum((P_mat - ProjPt).^2, 2));
    [~, idx] = min(dists);
end
