#include <iostream>
#include <vector>
#include <string>

using namespace std;

/**
 * Problem Analysis:
 * We need to fill in the missing characters ('_') at odd positions (1-based) of a string s of length n (even).
 * The even positions (2, 4, ..., n) are fixed with either '(' or ')'.
 * We need to construct a valid Regular Bracket Sequence (RBS) with minimum cost.
 * Cost is defined as the sum of distances between matching open and closing brackets.
 *
 * Strategy:
 * We process the string from left to right, maintaining a stack of indices of unmatched opening brackets.
 * This simulates the standard parenthesis matching algorithm.
 * At any odd position (where we have '_'), we have a choice:
 * 1. Place '(': Increment the balance (push index to stack).
 * 2. Place ')': Decrement the balance (match with top of stack and pop).
 *
 * To minimize the total cost (sum of closing_pos - opening_pos), we intuitively want to:
 * - Keep the sum of closing positions small (close brackets as early as possible).
 * - Keep the sum of opening positions large (open brackets as late as possible).
 *
 * This aligns with a greedy strategy: Whenever we are at an odd position '_' and the current balance
 * (number of unmatched open brackets) is greater than 0, we should place a closing bracket ')'.
 * This minimizes the current closing position relative to the corresponding open bracket.
 * If the balance is 0, we are forced to place an opening bracket '(' to maintain validity (balance >= 0).
 *
 * Complexity:
 * Time: O(N) per test case (single pass).
 * Space: O(N) for the stack.
 */

void solve() {
    int n;
    if (!(cin >> n)) return;
    string s;
    cin >> s;

    // Stack to store the indices (1-based) of open brackets
    vector<int> st;
    st.reserve(n); // Reserve memory to avoid reallocations
    long long cost = 0;

    for (int i = 0; i < n; ++i) {
        int pos = i + 1; // Current 1-based position

        if (i % 2 == 0) { 
            // Odd position (1-based) corresponds to index i=0, 2, 4... in 0-based string.
            // These are the '_' positions we need to fill.
            if (st.empty()) {
                // No open brackets available to match. Must place '('.
                st.push_back(pos);
            } else {
                // We have open brackets. Greedily place ')' to minimize distance.
                // It matches with the most recently added unmatched open bracket (LIFO).
                int u = st.back();
                st.pop_back();
                cost += (long long)(pos - u);
            }
        } else {
            // Even position (1-based) corresponds to index i=1, 3, 5... in 0-based string.
            // These are the fixed brackets.
            if (s[i] == '(') {
                // Fixed '(': Always open.
                st.push_back(pos);
            } else {
                // Fixed ')': Must match with a pending open bracket.
                // By problem statement, a valid restoration is guaranteed, so stack won't be empty.
                int u = st.back();
                st.pop_back();
                cost += (long long)(pos - u);
            }
        }
    }
    cout << cost << "\n";
}

int main() {
    // Optimize I/O operations for performance
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}
