// Function to solve each test case
void solve() {
    int n;
    if (!(cin >> n)) return;
    vector<int> x(n);
    for (int i = 0; i < n; ++i) {
        cin >> x[i];
    }
    // The problem statement implies sorted input, but sorting ensures correctness
    sort(x.begin(), x.end());

    // Calculate the maximum distance P can be from each point x[i]
    // such that P is considered "closest" or "equally closest".
    // For P to be the closest point to x[i], the distance dist(x[i], P)
    // must be <= the distance from x[i] to its closest existing neighbor.
    // The closest existing neighbor is either the previous or the next point in the sorted list.
    vector<int> limit(n);
    for (int i = 0; i < n; ++i) {
        int d_left = (i > 0) ? x[i] - x[i - 1] : 1000000; 
        int d_right = (i < n - 1) ? x[i + 1] - x[i] : 1000000;
        limit[i] = min(d_left, d_right);
    }

    bool possible = false;
    // We need to find an integer P not in x such that for all i, |x[i] - P| <= limit[i].
    // Given the constraints (1 <= x_i <= 100), the valid P will likely be within the range [1, 100].
    // To be safe against edge cases where P might fall on boundaries, we search a slightly wider range,
    // e.g., 0 to 200. Since coordinates are small, this check is extremely fast.
    for (int p = 0; p <= 200; ++p) {
        // Check if P is already in the set (must be distinct)
        bool in_set = false;
        for (int val : x) {
            if (val == p) {
                in_set = true;
                break;
            }
        }
        if (in_set) continue;

        bool ok = true;
        for (int i = 0; i < n; ++i) {
            // Check if P satisfies the condition for point x[i]
            if (abs(x[i] - p) > limit[i]) {
                ok = false;
                break;
            }
        }

        if (ok) {
            possible = true;
            break;
        }
    }

    if (possible) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
}

int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}
